INSERT INTO "classifications" VALUES(2,'claude-haiku-5-5','2026-10-16T15:05:13Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "US", "name": "U.S. forecasters (National Hurricane Center)", "type": "RSMC"}], "confidence": 0.85, "countries": ["MX"], "dissemination_channels": [], "event_date": "2026-10-16", "event_location": "Pacific coast, Mexico", "event_name": "Hurricane Trudy", "ew4all_pillars": [2], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "en", "lead_time": null, "lead_time_hours": null, "original_title": "Hurricane Trudy strengthens to a Category 3 storm off Mexico Pacific coast", "outcome": "not_reported", "outcome_justification": "The snippet reports forecaster monitoring and intensity estimates but no warnings dissemination, actions taken, or outcomes.", "relevant": true, "review": false, "summary_en": "U.S. forecasters reported early Friday that Hurricane Trudy had strengthened to a Category 3 hurricane off Mexico''s Pacific coast, with maximum sustained winds of 120 mph. The item documents monitoring and intensity forecasting of the storm, but the snippet does not describe warnings issued, dissemination, or outcomes.", "summary_original": null, "title_en": "Hurricane Trudy strengthens to a Category 3 storm off Mexico Pacific coast", "wmo_regions": ["IV"]}');
