INSERT INTO "classifications" VALUES(1490,'claude-haiku-5-5','2026-10-18T03:08:50Z',1,0.93,0,'{"actions_taken": [], "agencies": [{"country": "PH", "name": "PAGASA", "type": "NMHS"}], "confidence": 0.93, "countries": ["PH"], "dissemination_channels": ["other"], "event_date": "2026-10-20", "event_location": null, "event_name": "Super Typhoon Champi (Rosal)", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "en", "lead_time": "expected to enter PAR on Tuesday, Oct. 20 (announced Oct. 18)", "lead_time_hours": 48, "original_title": "Super Typhoon Champi to enter PAR on Oct. 20; to be named Rosal", "outcome": "not_reported", "outcome_justification": "Article reports PAGASA''s forecast and expected entry into the PAR, but no outcomes are given in the snippet.", "relevant": true, "review": false, "summary_en": "PAGASA''s 5 a.m. bulletin on Sunday reported that Super Typhoon Champi is expected to enter the Philippine Area of Responsibility on Tuesday, October 20, where it will be named Rosal. The forecast warns of strong winds and heavy rains over northern Luzon and Bicol.", "summary_original": null, "title_en": "Super Typhoon Champi to enter PAR on Oct. 20; to be named Rosal", "wmo_regions": ["II", "V"]}');
INSERT INTO "classifications" VALUES(1529,'claude-haiku-5-5','2026-10-18T03:08:54Z',1,0.85,0,'{"actions_taken": ["JMA forecasting typhoon track and advising the public to follow further information"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-22", "event_location": "Waters south of Okinawa, Japan", "event_name": "Typhoon No. 30 (2026)", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "about 4 days ahead of expected arrival near Okinawa (around 22 October)", "lead_time_hours": null, "original_title": "台風30号 22日ごろ沖縄の南海上に達する予想 今後の情報に注意", "outcome": "not_reported", "outcome_justification": "The item only describes a forecast and advisory for a typhoon still developing; no outcome has been reported yet.", "relevant": true, "review": false, "summary_en": "NHK reports that the very strong Typhoon No. 30 is intensifying as it moves west over the sea south of Japan and is expected to reach waters south of Okinawa around Thursday 22 October. The track beyond that point is not yet settled, and the Japan Meteorological Agency is urging the public to follow its further information.", "summary_original": "非常に強い台風30号は、日本のはるか南の海上を発達しながら西寄りに進んでいます。22日木曜日ごろには沖縄の南の海上に達すると予想されていますが、その後の進路の予測は定まっておらず、気象庁は今後の情報に注意を呼びかけています。", "title_en": "Typhoon No. 30 expected to reach waters south of Okinawa around the 22nd; watch for further information", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(1556,'claude-haiku-5-5','2026-10-18T03:08:15Z',1,0.85,0,'{"actions_taken": ["NTT Docomo identified and fixed a system fault that prevented delivery of emergency earthquake alerts (Area Mail) to its mobile phones"], "agencies": [{"country": "JP", "name": "NTT Docomo", "type": "other"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["cell_broadcast"], "event_date": "2026-10-16", "event_location": null, "event_name": null, "ew4all_pillars": [3], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "緊急地震速報配信されなかったNTTドコモの不具合、対応が完了", "outcome": "negative", "outcome_justification": "Earthquake early warnings sent via Area Mail were not delivered to Docomo mobile phones during the 16 October earthquake, a dissemination failure; the fix was announced on 17 October.", "relevant": true, "review": false, "summary_en": "Following the 16 October earthquake in Japan, NTT Docomo''s mobile phones failed to receive emergency earthquake early warnings sent through the Area Mail system. On 17 October the company announced that it had completed the fix for the underlying system fault. The item concerns a failure in the warning dissemination pillar.", "summary_original": "16日の地震で緊急地震速報を伝える「エリアメール」がNTTドコモの携帯電話に配信されなかった問題で、ドコモは17日、原因となったシステムの不具合への対応が完了したと発表した。", "title_en": "Fix completed for NTT Docomo system glitch that failed to deliver earthquake early warnings", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(1583,'claude-haiku-5-5','2026-10-18T03:08:57Z',1,0.85,0,'{"actions_taken": ["Sheinbaum called for extreme precautions regarding rain, strong winds and flooding"], "agencies": [{"country": "MX", "name": "Presidencia de México (Sheinbaum government)", "type": "other"}], "confidence": 0.85, "countries": ["MX"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Jalisco and Colima, Mexico", "event_name": "Hurricane Trudy", "ew4all_pillars": [3, 4], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Lloverá sobre mojado: Sheinbaum alerta por Trudy y frente frío 2; estos son los 9 estados con lluvias – El Financiero", "outcome": "not_reported", "outcome_justification": "The snippet reports a warning and call for precautions but no outcomes are yet described.", "relevant": true, "review": false, "summary_en": "Hurricane Trudy strengthened to Category 2 as it approaches the coasts of Jalisco and Colima, Mexico. President Sheinbaum asked for extreme precautions against heavy rain, strong winds and flooding, and the article lists nine states expected to receive rain from Trudy and a second cold front.", "summary_original": "El huracán ''Trudy'' se fortaleció a categoría 2 mientras se acerca a las costas de Jalisco y Colima. Sheinbaum pidió extremar precauciones ante las lluvias, fuertes vientos e inundaciones.", "title_en": "Rain over wet ground: Sheinbaum warns of Trudy and cold front 2; these are the 9 states with rain", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(1584,'claude-haiku-5-5','2026-10-18T03:10:01Z',1,0.85,0,'{"actions_taken": [], "agencies": [], "confidence": 0.85, "countries": ["US"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": null, "event_name": "Hurricane Isaías", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Huracán Isaías se eleva a categoría 2 mientras se dirige al sur de EE. UU. - Dominican Republic Post – Caribbean News, Business, Travel & Culture", "outcome": "not_reported", "outcome_justification": "The snippet reports the storm''s intensification and track toward the southern US but gives no information on warnings received, actions taken or their effects.", "relevant": true, "review": false, "summary_en": "Hurricane Isaías intensified to Category 2 with maximum sustained winds of 100 mph (155 km/h) while moving toward the southern United States. The report is a news update on the storm''s strengthening and track, without details of the forecasts, warnings or dissemination efforts issued.", "summary_original": "El huracán Isaías se intensificó este jueves a categoría 2, con vientos máximos de 100 millas por hora (155 kilómetros por hora), mientras se dirige al sur de Estados Unidos.", "title_en": "Hurricane Isaías strengthens to Category 2 as it heads toward the southern US", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(1585,'claude-haiku-5-5','2026-10-18T03:08:30Z',1,0.9,0,'{"actions_taken": ["Public alert issued by Protección Civil", "Call by the President to take extreme precautions"], "agencies": [{"country": "MX", "name": "Protección Civil (Mexico)", "type": "other_national_agency"}, {"country": "MX", "name": "Government of Mexico (Claudia Sheinbaum)", "type": "other"}], "confidence": 0.9, "countries": ["MX"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Colima and Michoacán, Mexico", "event_name": "Hurricane Trudy", "ew4all_pillars": [3, 4], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Protección Civil alerta por el fortalecimiento de Trudy a huracán categoría 2 frente a Colima y Michoacán", "outcome": "not_reported", "outcome_justification": "The snippet reports a warning and precautionary call but gives no information on outcomes or impacts.", "relevant": true, "review": false, "summary_en": "Mexico''s Civil Protection issued an alert as Trudy was forecast to strengthen into a Category 2 hurricane approaching the coasts of Colima and Michoacán. President Claudia Sheinbaum called for extreme precautions in response to the phenomenon.", "summary_original": "Protección Civil emitió una alerta por el fortalecimiento de Trudy a huracán categoría 2 frente a Colima y Michoacán, y la presidenta Claudia Sheinbaum llamó a extremar precauciones ante el fenómeno meteorológico.", "title_en": "Civil Protection warns of Trudy strengthening to Category 2 hurricane off Colima and Michoacán", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(1587,'claude-haiku-5-5','2026-10-18T03:08:34Z',1,0.85,0,'{"actions_taken": [], "agencies": [], "confidence": 0.85, "countries": ["AR"], "dissemination_channels": ["website"], "event_date": "2026-10-18", "event_location": "Chaco, Argentina", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta roja para Puerto Antequeras, Barranqueras y otras localidades de Chaco", "outcome": "not_reported", "outcome_justification": "The snippet reports a red flood alert issued for several localities along the Paraná River but gives no information on actions taken or results.", "relevant": true, "review": false, "summary_en": "A red alert has been issued for Puerto Antequeras, Barranqueras, Vilelas, Isla del Cerrito and San Pedro Pescador in Chaco due to a rise of the Paraná River. The alert indicates a high-level flood warning for these localities, though the snippet provides no details on forecasts, dissemination or response.", "summary_original": "Alerta roja por la crecida del río Paraná para Puerto Antequeras, Barranqueras, Vilelas, Isla del Cerrito y San Pedro Pescador en la provincia de Chaco.", "title_en": "Red alert for Puerto Antequeras, Barranqueras and other localities in Chaco", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1588,'claude-haiku-5-5','2026-10-18T03:09:01Z',1,0.85,0,'{"actions_taken": ["Government call for population to take precautions against Hurricane Trudy and Cold Front 2"], "agencies": [{"country": "MX", "name": "Presidencia de México", "type": "other"}], "confidence": 0.85, "countries": ["MX"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Colima, Michoacán, Jalisco, Nayarit, Guerrero, Chiapas, Tabasco, Oaxaca and Veracruz, Mexico", "event_name": "Hurricane Trudy", "ew4all_pillars": [3, 4], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Sheinbaum reitera llamado a tomar precauciones por huracán Trudy y Frente Frío 2", "outcome": "not_reported", "outcome_justification": "Snippet only describes a precautionary call and the states named in the warning; no outcomes are reported.", "relevant": true, "review": false, "summary_en": "The Mexican President reiterated a call for precautions in the face of Hurricane Trudy and Cold Front 2. The warning covers several Pacific and Gulf states, including Colima, Michoacán, Jalisco, Nayarit, Guerrero, Chiapas, Tabasco, Oaxaca and Veracruz. The snippet does not detail the forecasts, dissemination channels or outcomes.", "summary_original": "La presidenta Sheinbaum reiteró el llamado a tomar precauciones ante el huracán Trudy y el Frente Frío 2, con aviso que señala a varios estados del Pacífico y del Golfo de México.", "title_en": "Sheinbaum reiterates call to take precautions for Hurricane Trudy and Cold Front 2", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(1589,'claude-haiku-5-5','2026-10-18T03:10:04Z',1,0.95,0,'{"actions_taken": ["Activation of ES-Alert in four comarcas of Barcelona"], "agencies": [{"country": "ES", "name": "Protecció Civil (Generalitat de Catalunya)", "type": "other_national_agency"}, {"country": "ES", "name": "Meteocat", "type": "NMHS"}], "confidence": 0.95, "countries": ["ES"], "dissemination_channels": ["cell_broadcast"], "event_date": "2026-10-18", "event_location": "Barcelona, Spain", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta por lluvias torrenciales en Barcelona: la ES - Alert suena en el móvil hasta las 2 h", "outcome": "not_reported", "outcome_justification": "The snippet reports the warning activation and forecast of four days of rain and cold, but gives no information on impacts or public response.", "relevant": true, "review": false, "summary_en": "Civil Protection activated the ES-Alert mobile warning system in four comarcas of Barcelona due to torrential rain valid until 2 a.m. Meteocat forecasts four days of rain and cold. The item documents warning dissemination via cell broadcast and a multi-day rainfall forecast.", "summary_original": "Protecció Civil activó la ES-Alert en cuatro comarcas de Barcelona por lluvias torrenciales hasta las 2 h, y Meteocat prevé cuatro días de lluvia y frío.", "title_en": "Torrential rain alert in Barcelona: ES-Alert sounds on mobile phones until 2 a.m.", "wmo_regions": ["VI"]}');
