INSERT INTO "classifications" VALUES(1596,'claude-haiku-5-5','2026-10-18T03:09:34Z',1,0.7,0,'{"actions_taken": ["Evacuation of nearly 500 people from six localities"], "agencies": [], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Entre Ríos Province, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 500, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Acá no te ayuda nadie: el reclamo de los vecinos evacuados por la crecida de los ríos Paraná y Uruguay", "outcome": "negative", "outcome_justification": "Residents complain of lack of support after evacuation; no information on warning timeliness or dissemination is given, but the complaint about insufficient assistance points to response shortcomings.", "relevant": true, "review": false, "summary_en": "Authorities recorded almost 500 people forced to leave their homes in six localities of the province due to rising waters of the Paraná and Uruguay rivers. Coastal areas remain on alert and new floods are feared. Evacuated residents complain they are receiving little help.", "summary_original": "Las autoridades registraron casi quinientas personas que debieron abandonar sus hogares en seis localidades de la provincia por la crecida de los ríos Paraná y Uruguay. Los vecinos evacuados reclaman falta de asistencia mientras las zonas costeras siguen en alerta.", "title_en": "Nobody helps us here: residents evacuated by the flooding of the Paraná and Uruguay rivers complain", "wmo_regions": ["III"]}');
