INSERT INTO "classifications" VALUES(1612,'claude-haiku-5-5','2026-10-18T03:10:48Z',1,0.7,0,'{"actions_taken": ["Evacuation of over 400 people from their homes", "Relocation of evacuees to Casa Promesera and Taba Cué lodging"], "agencies": [], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Itatí, Corrientes, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 400, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Corrientes: tras la crecida de los ríos Paraná y Uruguay más de 400 personas abandonaron sus hogares", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations after river flooding but does not state whether warnings were issued in advance or how they were received.", "relevant": true, "review": false, "summary_en": "Following the rise of the Paraná and Uruguay rivers in Corrientes province, Argentina, more than 400 people were evacuated from their homes. Itatí was the most affected locality, with 110 people from 43 families moved to the Casa Promesera and Taba Cué lodging. The snippet does not describe the early warnings or forecasts that preceded the evacuations.", "summary_original": "Tras la crecida de los ríos Paraná y Uruguay, más de 400 personas fueron evacuadas en Corrientes. Itatí es la localidad más afectada, con 110 personas de 43 familias trasladadas a la Casa Promesera y al hospedaje Taba Cué.", "title_en": "Corrientes: after the rise of the Paraná and Uruguay rivers, more than 400 people left their homes", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1615,'claude-haiku-5-5','2026-10-18T03:10:53Z',1,0.8,0,'{"actions_taken": ["Families advised to keep emergency bags prepared", "Households advised to agree on how to act in case of flooding"], "agencies": [{"country": "UY", "name": "Sistema Nacional de Emergencias (Sinae)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["UY"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Uruguay", "event_name": null, "ew4all_pillars": [1, 3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Sinae: acuerdos entre personas cercanas y una mochila con un kit de emergencia y evacuación", "outcome": "not_reported", "outcome_justification": "The item is a preparedness recommendation ahead of expected flooding linked to El Niño; no warning outcome is reported.", "relevant": true, "review": false, "summary_en": "Uruguay''s National Emergency System (Sinae) recommends families prepare emergency bags and agree on household response plans ahead of possible flooding that the El Niño phenomenon is expected to bring. The advice focuses on risk knowledge and preparedness rather than a specific warning event.", "summary_original": "El Sistema Nacional de Emergencias (Sinae) recomienda a las familias tener bolsos de emergencia preparados ante posibles inundaciones que, prevén, traerá el fenómeno del niño, y aconseja hacer un acuerdo en cada hogar sobre cómo actuar.", "title_en": "Sinae: agreements between close people and a backpack with an emergency and evacuation kit", "wmo_regions": ["III"]}');
