INSERT INTO "classifications" VALUES(1814,'claude-haiku-5-5','2026-10-19T03:24:31Z',1,0.85,0,'{"actions_taken": ["JMA warned of lightning, tornadoes and other gusty winds, and sudden heavy rain"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["tv"], "event_date": "2026-10-19", "event_location": "Western and eastern Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "severe_storm", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "through 20 October", "lead_time_hours": null, "original_title": "あすにかけ西日本や東日本中心に大気非常に不安定", "outcome": "not_reported", "outcome_justification": "The snippet reports JMA advisories on very unstable atmospheric conditions but gives no information on impacts or public response.", "relevant": true, "review": false, "summary_en": "A front-associated low-pressure system is producing developing rain clouds over Hokkaido, while western and eastern Japan are expected to experience very unstable atmospheric conditions through 20 October. The Japan Meteorological Agency warned of lightning, tornado-type gusty winds and sudden heavy rain.", "summary_original": "前線を伴った低気圧の影響で北海道では雨雲が発達している。西日本や東日本を中心に20日にかけて大気が非常に不安定となる見込みで、気象庁は落雷や竜巻などの突風、急な強い雨に注意を呼びかけている。", "title_en": "Atmosphere very unstable mainly over western and eastern Japan through tomorrow", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(1879,'claude-haiku-5-5','2026-10-19T03:24:28Z',1,0.95,0,'{"actions_taken": ["AEMET issued a red alert for rainfall of at least 300 l/m² in southern Valencia and northern Alicante"], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}], "confidence": 0.95, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-18", "event_location": "Southern coast of Valencia and northern Alicante, Spain", "event_name": "DANA Adam", "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta roja en Valencia y Alicante: municipios afectados, lluvias previstas y hasta cuándo hay riesgo de «impactos catastróficos»", "outcome": "not_reported", "outcome_justification": "The item reports the forecast and red alert issued, but no outcomes of the warning are given in the snippet.", "relevant": true, "review": false, "summary_en": "AEMET issued a red alert for the DANA Adam event, forecasting at least 300 l/m² of rain in southern Valencia and northern Alicante from midnight on 18 October until at least 10:00 on 19 October, with 200 l/m² expected in 12 hours and 300 l/m² in 24 hours. The article concerns the affected municipalities and how long the risk of catastrophic impacts persists.", "summary_original": "La Aemet decretó alerta roja por lluvias de al menos 300 litros por metro cuadrado en el litoral sur de Valencia y norte de Alicante, por la dana Adam, desde la medianoche del domingo 18 de octubre hasta como mínimo las 10:00 del lunes 19. Se prevén 200 litros en 12 horas y 300 litros en 24 horas.", "title_en": "Red alert in Valencia and Alicante: affected municipalities, expected rainfall and how long the risk of ''catastrophic impacts'' lasts", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(1880,'claude-haiku-5-5','2026-10-19T03:24:23Z',1,0.8,0,'{"actions_taken": ["Red alert declared for areas outside the defence system (Puerto Antequeras, Barranqueras, Chaco)", "Evacuation of 472 people from Entre Ríos and Corrientes river flood zones"], "agencies": [{"country": "AR", "name": "Comité Provincial de Emergencia de Chaco", "type": "other_national_agency"}, {"country": "AR", "name": "Defensa Civil (Entre Ríos)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-18", "event_location": "Chaco and Corrientes, Argentina", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 472, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "El Niño: crecen los ríos en el Litoral, prevén nuevas lluvias y aumenta la cantidad de evacuados - Infobae", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and alerts but does not state whether warnings were timely or effective.", "relevant": true, "review": false, "summary_en": "Provincial emergency authorities in Chaco declared a red alert for flood-prone sectors outside the defence system as the Paraná and Uruguay rivers rose amid El Niño-related rains. In Entre Ríos and Corrientes, 472 people were evacuated or relocated on their own, according to Civil Defence, and new rainfall was forecast.", "summary_original": "El Comité Provincial de Emergencia de Chaco declaró alerta roja para sectores fuera del sistema de defensas, y la crecida de los ríos Paraná y Uruguay obligó a 472 personas a evacuar o reubicarse en Corrientes, según Defensa Civil.", "title_en": "El Niño: rivers rise in the Litoral, new rains forecast and number of evacuees increases", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1882,'claude-haiku-5-5','2026-10-19T03:25:02Z',1,0.85,0,'{"actions_taken": ["INDECI recommends preparedness measures in response to SENAMHI Aviso N.° 424"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Coast and highlands, central and southern Peru", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heatwave", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "INDECI recomienda medidas de preparación ante el incremento de la temperatura diurna en la costa y sierra centro y sur", "outcome": "not_reported", "outcome_justification": "The snippet describes forecast-based advisories and recommended preparedness measures but reports no outcomes.", "relevant": true, "review": false, "summary_en": "INDECI recommends preparedness measures following SENAMHI Aviso N.° 424, which reports continued moderate to extreme increases in daytime temperatures on the coast and highlands of Peru. The item shows the advisory chain from the national meteorological service to the civil defence agency and the public.", "summary_original": "INDECI recomienda adoptar medidas de preparación ante el Aviso N.° 424 del SENAMHI, que informa la continuidad del incremento de la temperatura diurna, de moderada a extrema intensidad, en la costa y sierra del país.", "title_en": "INDECI recommends preparedness measures for increased daytime temperatures on the coast and highlands of central and southern Peru", "wmo_regions": ["III"]}');
