INSERT INTO "classifications" VALUES(2357,'claude-haiku-5-5','2026-10-20T03:18:11Z',1,0.8,0,'{"actions_taken": [], "agencies": [], "confidence": 0.8, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Valencian Community, Spain", "event_name": "Cut-off low Adam", "ew4all_pillars": [], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": 5, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La dana Adam se ceba en la Comunidad Valenciana con 3 muertos y deja cortes de luz y de carreteras en Baleares", "outcome": "not_reported", "outcome_justification": "The snippet reports deaths and infrastructure cuts but gives no information on warnings issued, their dissemination, or actions taken.", "relevant": true, "review": false, "summary_en": "The cut-off low (DANA) named Adam has caused five deaths: one in Cabrera de Mar (Barcelona), three in the Valencian Community and one in Málaga. It has also caused power outages and road closures in the Balearic Islands. The snippet does not describe any warnings or forecasts issued in advance.", "summary_original": "La dana Adam ha causado cinco fallecidos, uno en Cabrera de Mar (Barcelona), tres en la Comunidad Valenciana y otro en Málaga, además de cortes de luz y carreteras en Baleares.", "title_en": "Cut-off low ''Adam'' hits the Valencian Community with 3 deaths and leaves power and road cuts in the Balearic Islands", "wmo_regions": ["VI"]}');
