INSERT INTO "classifications" VALUES(2367,'claude-haiku-5-5','2026-10-20T03:17:05Z',1,0.8,0,'{"actions_taken": ["Evacuation of nearly 60,000 cattle from the islands of the Paraná River"], "agencies": [{"country": "AR", "name": "Sociedad Rural de Goya", "type": "other"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Corrientes Province, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Corrientes: la crecida del Paraná obliga a evacuar casi 60.000 vacunos de las islas", "outcome": "not_reported", "outcome_justification": "The snippet describes logistical difficulties and risks for rural workers during the evacuation but does not report whether warnings were timely or effective.", "relevant": true, "review": false, "summary_en": "Rising Paraná River waters are forcing the evacuation of nearly 60,000 cattle from islands in Corrientes Province. The president of the Goya Rural Society warned of logistical difficulties, risks to rural workers and uncertainty about further rainfall. The item relates to flood preparedness and response rather than explicitly documenting a forecast or warning.", "summary_original": "La crecida del Paraná obliga a evacuar casi 60.000 vacunos de las islas de Corrientes. Santiago Decotto, presidente de la Sociedad Rural de Goya, advirtió sobre dificultades logísticas, riesgos para los trabajadores y la incertidumbre ante posibles lluvias.", "title_en": "Corrientes: the Paraná flood forces evacuation of nearly 60,000 cattle from the islands", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2370,'claude-haiku-5-5','2026-10-20T03:18:49Z',1,0.8,0,'{"actions_taken": ["646 people evacuated across the province"], "agencies": [], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Corrientes Province, Argentina", "event_name": "El Niño", "ew4all_pillars": [2, 3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 646, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "peak expected Tuesday; water expected to recede toward southern localities within three weeks", "lead_time_hours": null, "original_title": "Fenómeno El Niño: Corrientes se prepara para la peor semana por la crecida del río Paraná", "outcome": "not_reported", "outcome_justification": "Article reports river nearing evacuation threshold, forecast peak and evacuations, but does not state whether warnings were effective or any shortcomings.", "relevant": true, "review": false, "summary_en": "The Paraná River in Corrientes reached 6.98 m on Sunday, just below the 7 m evacuation level, with a peak forecast for Tuesday. A total of 646 people have been evacuated across the province, and authorities warn the water will recede toward southern localities over the next three weeks.", "summary_original": "El río Paraná en Corrientes alcanzó 6,98 m el domingo, justo por debajo del nivel de evacuación de 7 m, con un pico previsto para el martes. Se han evacuado 646 personas en la provincia y las autoridades advierten que el agua bajará hacia el sur en las próximas tres semanas.", "title_en": "El Niño phenomenon: Corrientes prepares for worst week due to Paraná River flood", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2373,'claude-haiku-5-5','2026-10-20T03:15:45Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}], "confidence": 0.85, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Valencia and Alicante, Spain", "event_name": "Storm Adam", "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La dana Adam mantiene este lunes la alerta roja por lluvias en Valencia y Alicante antes de desplazarse a Cataluña", "outcome": "not_reported", "outcome_justification": "The snippet reports an active red rain alert and expected instability but gives no information on impacts or the effectiveness of the warnings.", "relevant": true, "review": false, "summary_en": "The DANA Adam system is expected to maintain unstable weather over the Iberian Peninsula and Balearic Islands on Monday, with a red rain alert in force in Valencia and Alicante before the system moves toward Catalonia. The item reports the warning status and expected movement of the system, but no impacts or outcomes yet.", "summary_original": "La dana Adam mantendrá este lunes una situación de inestabilidad en la Península y Baleares, con una alerta roja por lluvias en Valencia y Alicante antes de desplazarse hacia Cataluña.", "title_en": "Storm Adam keeps red rain alert on Monday in Valencia and Alicante before moving to Catalonia", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2374,'claude-haiku-5-5','2026-10-20T03:19:01Z',1,0.85,0,'{"actions_taken": ["Alert status maintained in Catalonia"], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}], "confidence": 0.85, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Valencia, Spain", "event_name": "DANA Adam", "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": 3, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Personas atrapadas en los tejados y carreteras cortadas por la dana Adam que azota Levante", "outcome": "not_reported", "outcome_justification": "The snippet reports deaths and people trapped but does not say whether warnings were issued in advance or how they were received.", "relevant": true, "review": false, "summary_en": "Heavy rain associated with DANA Adam has left at least three dead in the province of Valencia, one in Barcelona and one in Malaga, with people trapped on rooftops and roads cut. The rains are moving northeast and keeping Catalonia on alert. The snippet does not detail the warnings issued in advance.", "summary_original": "Las lluvias de la DANA Adam dejan al menos tres muertos en la provincia de Valencia, uno en Barcelona y otro en Málaga, con personas atrapadas en tejados y carreteras cortadas; se dirigen al nordeste y mantienen en alerta a Cataluña.", "title_en": "People trapped on rooftops and roads cut as DANA Adam lashes Levante", "wmo_regions": ["VI"]}');
