INSERT INTO "classifications" VALUES(2376,'claude-haiku-5-5','2026-10-20T03:16:18Z',1,0.85,0,'{"actions_taken": ["Preventive intervention by emergency services in Mallorca"], "agencies": [{"country": "ES", "name": "Emergency services (Mallorca)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Mallorca, Balearic Islands, Spain", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "severe_storm", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Pocos incidentes durante la noche en Mallorca, Ibiza y Formentera, pese a la alerta roja", "outcome": "mixed", "outcome_justification": "Red alert was in force and only two tree falls were recorded in Mallorca overnight, suggesting limited impacts, but the snippet does not establish whether the warning itself caused the low incident count.", "relevant": true, "review": false, "summary_en": "A red weather alert was in force across Mallorca, Ibiza and Formentera overnight. Between 22:00 Sunday and 06:30 Monday, Mallorca recorded two fallen trees and one preventive intervention, with few incidents reported across the islands. The snippet does not detail the forecasting or dissemination of the alert.", "summary_original": "Entre las 22 horas del domingo y las 6.30 horas del lunes, en Mallorca se contabilizaron dos caídas de árboles y una intervención preventiva, con pocos incidentes en las islas pese a la alerta roja vigente.", "title_en": "Few incidents overnight in Mallorca, Ibiza and Formentera despite red alert", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2377,'claude-haiku-5-5','2026-10-20T03:17:16Z',1,0.8,0,'{"actions_taken": ["Evacuations reported", "Opening of dam floodgates"], "agencies": [{"country": "AR", "name": "Represas (dam operators)", "type": "other"}], "confidence": 0.8, "countries": ["AR", "UY"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Litoral region, Argentina", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "¿ Puede pasar en la Región?: alerta por la crecida de los ríos del Litoral", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and dam gate openings due to rising flows, but does not state whether warnings were timely or effective.", "relevant": true, "review": false, "summary_en": "The Paraná and Uruguay rivers are recording strong flow increases, prompting evacuations and the opening of dam floodgates. Concern is raised about the large volumes of water reaching the Río de la Plata. The snippet does not detail the forecasts or warnings issued.", "summary_original": "El Paraná y el Uruguay registran fuertes aumentos de caudal, con evacuaciones y apertura de compuertas en las represas, lo que genera preocupación por la llegada de grandes masas de agua al Río de la Plata.", "title_en": "Could it happen in the Region?: alert over flooding of the Litoral rivers", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2379,'claude-haiku-5-5','2026-10-20T03:17:20Z',1,0.95,0,'{"actions_taken": ["Class suspensions in affected areas"], "agencies": [{"country": "ES", "name": "ES-alert", "type": "other_national_agency"}], "confidence": 0.95, "countries": ["ES"], "dissemination_channels": ["mobile_app"], "event_date": "2026-10-19", "event_location": "Southern Valencia and northern Alicante, Spain", "event_name": "DANA Adam", "ew4all_pillars": [3, 4], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Última hora del temporal, en directo: Peligro extraordinario en el Mediterráneo por la DANA Adam que mantiene los avisos rojos en el sur de Valencia y norte de Alicante", "outcome": "not_reported", "outcome_justification": "The snippet reports the ES-alert being triggered again and school closures, but gives no information on whether warnings were effective or on any casualties or losses.", "relevant": true, "review": false, "summary_en": "A live news update reports that red warnings remain in place for southern Valencia and northern Alicante due to DANA Adam, described as an extraordinary Mediterranean hazard. The ES-alert emergency alert system was triggered again and classes were suspended, with the situation described as the worst moment of the event.", "summary_original": "Una actualización en directo informa de que los avisos rojos se mantienen en el sur de Valencia y el norte de Alicante por la DANA Adam, un peligro extraordinario en el Mediterráneo. El sistema ES-alert volvió a sonar y se suspendieron las clases, en lo que se describe como el peor momento del episodio.", "title_en": "Latest on the storm, live: Extraordinary danger in the Mediterranean due to DANA Adam, with red warnings maintained in southern Valencia and northern Alicante", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2380,'claude-haiku-5-5','2026-10-20T03:19:06Z',1,0.85,0,'{"actions_taken": [], "agencies": [], "confidence": 0.85, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Coquimbo to Biobío regions, Chile", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta climática en zona central de Chile por sistema frontal", "outcome": "not_reported", "outcome_justification": "The snippet reports an active alert for a new frontal system with rain and hail that could cause debris flows, but no outcome is described.", "relevant": true, "review": false, "summary_en": "Central Chile, from Coquimbo to Biobío, is under a climate alert for a new frontal system bringing rain and hail that could cause debris flows (aluviones). The item describes the alert status but does not detail the forecasting agency, dissemination channels, or any protective actions.", "summary_original": "La zona central de Chile, desde Coquimbo hasta el Biobío, está en fase de alerta climática por un nuevo sistema frontal con lluvias y granizo que podrían causar aluviones.", "title_en": "Climate alert in central Chile due to frontal system", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2382,'claude-haiku-5-5','2026-10-20T03:15:22Z',1,0.9,0,'{"actions_taken": ["evacuation of hundreds of families", "monitoring of river flows at Itaipú and Yacyretá"], "agencies": [{"country": "PY", "name": "Itaipú", "type": "other"}, {"country": "AR", "name": "Yacyretá", "type": "other"}], "confidence": 0.9, "countries": ["PY"], "dissemination_channels": [], "event_date": "2026-10-18", "event_location": "Ciudad del Este, Paraguay", "event_name": null, "ew4all_pillars": [2, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 1200, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta roja en Ciudad del Este: la histórica crecida del río Paraná ya deja más de 1.200 evacuados", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and flow monitoring but does not state whether warnings were timely or effective.", "relevant": true, "review": false, "summary_en": "A historic flood of the Paraná River has forced evacuation of more than 1,200 people in the low-lying area of Ciudad del Este, with water above 15 metres. Authorities are monitoring dam discharges at Itaipú and Yacyretá amid forecasts of new storms linked to El Niño, and there are concerns about dengue from stagnant water.", "summary_original": "Las históricas inundaciones en la zona baja de Ciudad del Este obligaron a evacuar a cientos de familias, con agua por encima de 15 metros. Las autoridades vigilan los caudales de Itaipú y Yacyretá ante pronósticos de nuevas tormentas por El Niño.", "title_en": "Red alert in Ciudad del Este: historic Paraná River flood already leaves more than 1,200 evacuated", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2383,'claude-haiku-5-5','2026-10-20T03:19:15Z',1,0.8,0,'{"actions_taken": ["Evacuations reported as increasing"], "agencies": [{"country": "AR", "name": "Subsecretaría de Recursos Hídricos (Hydrology sector)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-18", "event_location": "Litoral region, Argentina", "event_name": null, "ew4all_pillars": [2], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Crecen los ríos en el Litoral, prevén nuevas lluvias y aumenta la cantidad de evacuados", "outcome": "not_reported", "outcome_justification": "The snippet reports rising rivers, forecast rains and growing evacuee numbers but does not state whether warnings led to timely action or losses avoided.", "relevant": true, "review": false, "summary_en": "Argentina''s Litoral region faces rising rivers linked to El Niño, which the hydrology sector warned will intensify between October and February. New rains are forecast and the number of evacuees is increasing. The snippet does not detail specific warning dissemination.", "summary_original": "El fenómeno de El Niño sigue afectando el Litoral argentino; la jefa de Hidrología advirtió que se intensificará entre octubre y febrero, mientras crecen los ríos, se prevén nuevas lluvias y aumentan los evacuados.", "title_en": "Rivers rise in the Litoral, new rains forecast and number of evacuees increases", "wmo_regions": ["III"]}');
