INSERT INTO "classifications" VALUES(2387,'claude-haiku-5-5','2026-10-20T03:19:24Z',1,0.8,0,'{"actions_taken": ["Mobilisation of the UME", "Suspension of classes in the Balearic Islands"], "agencies": [{"country": "ES", "name": "UME (Unidad Militar de Emergencias)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-18", "event_location": "Balearic Islands, Spain", "event_name": "DANA Adam", "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": 1, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La dana Adam deja una mujer muerta, moviliza a la UME y obliga a suspender las clases en Baleares", "outcome": "not_reported", "outcome_justification": "The snippet mentions a death and emergency mobilisation but does not state whether warnings were timely or effective.", "relevant": true, "review": false, "summary_en": "A DANA (cut-off low) named Adam caused one reported death, prompted the mobilisation of Spain''s UME emergency unit and led to class suspensions in the Balearic Islands, amid a red alert for rain. The item signals warnings were in force, though details on forecast lead time and dissemination are not given.", "summary_original": "La DANA Adam deja una mujer muerta, moviliza a la UME y obliga a suspender las clases en Baleares, en un contexto de alerta roja por lluvias.", "title_en": "Dana Adam leaves one woman dead, mobilises the UME and forces class suspensions in the Balearic Islands", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2389,'claude-haiku-5-5','2026-10-20T03:19:27Z',1,0.9,0,'{"actions_taken": ["Suspension of classes in Mallorca, Eivissa and Formentera", "Deployment of the UME", "Request that the population stay at home"], "agencies": [{"country": "ES", "name": "Government of Spain", "type": "other_national_agency"}, {"country": "ES", "name": "UME (Unidad Militar de Emergencias)", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["ES"], "dissemination_channels": ["cell_broadcast"], "event_date": "2026-10-18", "event_location": "Mallorca, Eivissa and Formentera, Balearic Islands, Spain", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La dana obliga a suspender clases en Mallorca, Eivissa y Formentera y moviliza a la UME", "outcome": "not_reported", "outcome_justification": "The snippet reports warning dissemination and response actions but gives no information on results or impacts.", "relevant": true, "review": false, "summary_en": "Spanish authorities sent an Es-Alert emergency message to the population of the Balearic Islands and asked residents to remain at home due to a DANA (cut-off low) event. Classes were suspended in Mallorca, Eivissa and Formentera and the UME was mobilised. The snippet gives no information on outcomes.", "summary_original": "El Gobierno envió un Es-Alert a la población y le pidió que permaneciera en sus casas, mientras se suspendían las clases en Mallorca, Eivissa y Formentera y se movilizaba a la UME por la DANA.", "title_en": "The DANA forces class suspensions in Mallorca, Eivissa and Formentera and mobilises the UME", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2390,'claude-haiku-5-5','2026-10-20T03:15:48Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}], "confidence": 0.9, "countries": ["ES"], "dissemination_channels": ["other"], "event_date": "2026-10-18", "event_location": "Valencia, Alicante, Ibiza and Formentera, Spain", "event_name": "DANA Adam", "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La dana Adam pone en alerta roja a Valencia, Alicante, Ibiza y Formentera por lluvias torrenciales", "outcome": "not_reported", "outcome_justification": "The snippet reports a red alert and flood risk but gives no information on impacts or the effectiveness of the warnings.", "relevant": true, "review": false, "summary_en": "A cold air mass and two DANAs (cut-off low systems) are expected to sustain instability in Spain, with flood risk. Red alerts have been issued for Valencia, Alicante, Ibiza and Formentera due to torrential rain.", "summary_original": "Una masa de aire frío y la formación de dos danas mantendrán la inestabilidad en España, con riesgo de inundaciones. Se han emitido alertas rojas para Valencia, Alicante, Ibiza y Formentera por lluvias torrenciales.", "title_en": "The DANA Adam puts Valencia, Alicante, Ibiza and Formentera on red alert for torrential rain", "wmo_regions": ["VI"]}');
