INSERT INTO "classifications" VALUES(2397,'claude-haiku-5-5','2026-10-20T03:16:28Z',1,0.85,0,'{"actions_taken": [], "agencies": [], "confidence": 0.85, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-18", "event_location": "Valencia and Alicante, Spain", "event_name": "Adam", "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Adam mantiene el lunes la alerta roja en Valencia y Alicante | Noticias Diario de Burgos", "outcome": "not_reported", "outcome_justification": "The snippet reports a red alert maintained for Valencia and Alicante and significant incidents on the Mediterranean coast, but does not state whether warnings led to any specific protective actions or outcomes.", "relevant": true, "review": false, "summary_en": "A red alert for Valencia and Alicante is maintained on Monday as the first major autumn DANA (cut-off low) causes significant incidents along the Mediterranean coast, and the system is expected to move towards Catalonia. The item concerns an active warning for heavy rain in Spain''s Valencian and Alicante provinces. Details on warning dissemination or response actions are not given in the snippet.", "summary_original": "Adam mantiene el lunes la alerta roja en Valencia y Alicante. La primera gran dana del otoño causa significativas incidencias en el litoral mediterráneo y se espera que a lo largo de mañana se desplace hacia Cataluña.", "title_en": "Adam keeps red alert in Valencia and Alicante on Monday", "wmo_regions": ["VI"]}');
