INSERT INTO "classifications" VALUES(2400,'claude-haiku-5-5','2026-10-20T03:19:37Z',1,0.6,0,'{"actions_taken": ["Evacuation of families", "Habilitation of accommodation spaces in Itatí", "Local chapel used as temporary shelter in Isla Apipé Chico"], "agencies": [], "confidence": 0.6, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-18", "event_location": "Itatí, Corrientes, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La crecida del Paraná golpea a Corrientes: Itatí e Isla Apipé Chico, entre las zonas más afectadas", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and shelters but does not state whether warnings were issued in advance or how they performed.", "relevant": true, "review": false, "summary_en": "Rising waters of the Paraná River have left several localities in Corrientes province on alert, with homes, coastal zones and island areas affected. Families evacuated from Itatí are being housed in enabled accommodation spaces, while a chapel in Isla Apipé Chico serves as a temporary refuge. The snippet does not describe the warnings or forecasts issued beforehand.", "summary_original": "La crecida del río Paraná mantiene en alerta a distintas localidades de Corrientes, con viviendas, zonas costeras y sectores insulares afectados. En Itatí se habilitaron espacios de alojamiento para familias evacuadas, y en Isla Apipé Chico la capilla funciona como refugio temporal.", "title_en": "The Paraná flood hits Corrientes: Itatí and Isla Apipé Chico among the most affected areas", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2401,'claude-haiku-5-5','2026-10-20T03:15:29Z',1,0.9,0,'{"actions_taken": ["Red alert for rain in the southern coast of Valencia and northern Alicante was deactivated at 10:00 on 19 October", "Orange and yellow warnings for precipitation of up to 150 litres in twelve hours were maintained"], "agencies": [{"country": "ES", "name": "Aemet", "type": "NMHS"}], "confidence": 0.9, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Valencia and Alicante, Spain", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Aemet retira la alerta roja en Valencia y Alicante pero avisa de más lluvias de hasta 150 litros para este lunes", "outcome": "not_reported", "outcome_justification": "The snippet reports warning status changes but does not describe the outcomes of the warnings.", "relevant": true, "review": false, "summary_en": "Spain''s national meteorological service Aemet deactivated a red rain warning on 19 October 2026 for the southern Valencia coast and northern Alicante, while keeping orange and yellow warnings in place. The agency warned of precipitation of up to 150 litres in twelve hours for the following day.", "summary_original": "La Aemet desactivó la alerta roja por lluvias en el litoral sur de Valencia y norte de Alicante, manteniendo avisos naranjas y amarillos por precipitaciones de hasta 150 litros en doce horas.", "title_en": "Aemet withdraws red alert in Valencia and Alicante but warns of more rain of up to 150 litres for Monday", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2402,'claude-haiku-5-5','2026-10-20T03:15:18Z',1,0.85,0,'{"actions_taken": ["Government declared preventive emergency in O''Higgins, Maule and Metropolitan Region until 23 October", "Red alert issued for ten pre-Andean communes of Santiago", "Flood-risk alerts issued for five northern and central regions"], "agencies": [{"country": "CL", "name": "Government of Chile", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Santiago Metropolitan Region, O''Higgins and Maule regions, Chile", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Chile se prepara para un nuevo temporal que podría dejar inundaciones - Mundo - ABC Color", "outcome": "not_reported", "outcome_justification": "The article describes warnings and emergency declarations issued ahead of the storm but reports no outcomes yet.", "relevant": true, "review": false, "summary_en": "Chile''s government declared a preventive emergency in three central regions until 23 October and issued red alerts for ten pre-Andean communes of Santiago ahead of a new storm expected to cause flooding in five northern and central regions. The article focuses on warnings and preparedness measures; no impacts are reported yet.", "summary_original": "Chile se preparaba para un nuevo temporal con alertas por riesgo de inundaciones en cinco regiones del norte y centro; el Gobierno declaró emergencia preventiva hasta el 23 de octubre en O''Higgins, Maule y la Región Metropolitana, y alerta roja en diez comunas precordilleranas de Santiago.", "title_en": "Chile prepares for a new storm that could bring floods", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2407,'claude-haiku-5-5','2026-10-20T03:19:56Z',1,0.95,0,'{"actions_taken": ["INDECI recommends preparedness measures in response to SENAMHI Meteorological Warning No. 426 (orange level)"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.95, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Northern coast and highlands, Peru", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "INDECI recomienda medidas de preparación ante las precipitaciones en la costa norte y sierra", "outcome": "not_reported", "outcome_justification": "The snippet only describes recommended preparedness measures and the warning; no outcomes are reported.", "relevant": true, "review": false, "summary_en": "INDECI recommends preparedness measures in response to SENAMHI Meteorological Warning No. 426 at orange level, which reports moderate to strong precipitation (hail, rain, sleet and snow) affecting Peru''s northern coast and highlands. The item is a civil protection communication relaying an NMHS warning and its recommended actions.", "summary_original": "INDECI recomienda medidas de preparación ante el Aviso Meteorológico N.° 426 del SENAMHI (nivel naranja), que informa sobre precipitaciones de moderada a fuerte intensidad (granizo, lluvia, aguanieve y nieve) en la costa norte y sierra del país.", "title_en": "INDECI recommends preparedness measures ahead of rainfall in the northern coast and highlands", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2435,'claude-haiku-5-5','2026-10-20T03:16:57Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}], "confidence": 0.9, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Alicante, Spain", "event_name": "DANA Adam", "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Andalucía y Cataluña, bajo aviso naranja por ‘Adam’ tras pasar lo peor en la Comunidad Valenciana y Baleares", "outcome": "not_reported", "outcome_justification": "The snippet reports ongoing red and orange warnings and extraordinary rainfall totals but gives no information on the effectiveness of warnings or on actions taken.", "relevant": true, "review": false, "summary_en": "A DANA storm named ''Adam'' brought historic rainfall of over 700 litres per square metre in Alicante and nearly 600 in Valencia. Red warnings were in place in the Valencian Community and Balearic Islands, with orange warnings extending to Andalusia and Catalonia as the event moved on.", "summary_original": "Esta DANA está dejando precipitaciones extraordinarias e históricas de más de 700 litros en Alicante y de casi 600 en Valencia, mientras Andalucía y Cataluña quedan bajo aviso naranja.", "title_en": "Andalusia and Catalonia under orange alert for ''Adam'' after the worst has passed in Valencian Community and Balearic Islands", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2493,'claude-haiku-5-5','2026-10-20T03:15:39Z',1,0.8,0,'{"actions_taken": ["Rescue of people trapped by rain by firefighters, UME, Guardia Civil and other emergency services"], "agencies": [{"country": "ES", "name": "Bomberos", "type": "other_national_agency"}, {"country": "ES", "name": "UME (Unidad Militar de Emergencias)", "type": "other_national_agency"}, {"country": "ES", "name": "Guardia Civil", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Valencian Community, Spain", "event_name": "DANA Adam", "ew4all_pillars": [4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Los vídeos de los rescates en la Comunidad Valenciana durante la dana ‘Adam’", "outcome": "not_reported", "outcome_justification": "The snippet reports a red warning in force until 10 a.m. and emergency rescues, but does not state whether warnings led to measurable lives saved or shortcomings.", "relevant": true, "review": false, "summary_en": "A red warning, in force until 10 a.m. on Monday, mobilised firefighters, the UME, the Guardia Civil and other emergency services to rescue people trapped by rain during DANA ''Adam'' in the Valencian Community. The item is a video report on these rescues, and it does not detail the warning dissemination or its outcomes.", "summary_original": "El aviso rojo, que se mantuvo hasta las diez de la mañana de este lunes, movilizó a bomberos, UME, Guardia Civil y otros servicios de emergencia para rescatar a personas atrapadas por las lluvias.", "title_en": "Videos of the rescues in the Valencian Community during the DANA ''Adam''", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2494,'claude-haiku-5-5','2026-10-20T03:15:42Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}], "confidence": 0.85, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Valencian Community, Spain", "event_name": "DANA Adam", "ew4all_pillars": [3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Coches arrastrados por el agua y crecidas en los ríos: las imágenes de las lluvias en la Comunidad Valenciana", "outcome": "not_reported", "outcome_justification": "The snippet reports that the region remains under red warning during the most severe phase of DANA Adam, but gives no information on how warnings were disseminated or acted upon.", "relevant": true, "review": false, "summary_en": "Images show cars swept away and rivers in flood in the Valencian Community during DANA Adam. The region remains under a red warning on Monday, the most adverse phase of the event. The snippet does not describe the warning dissemination or response actions.", "summary_original": "La región continúa bajo aviso rojo este lunes, en la fase más adversa de la dana ‘Adam’, con coches arrastrados por el agua y crecidas en los ríos.", "title_en": "Cars swept away by water and river floods: images of the rains in the Valencian Community", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2572,'claude-haiku-5-5','2026-10-20T03:16:15Z',1,0.85,0,'{"actions_taken": ["Ministry of Defence activated a contingency plan in the Litoral region due to river flooding"], "agencies": [{"country": "AR", "name": "Servicio Meteorológico Nacional", "type": "NMHS"}, {"country": "AR", "name": "Ministerio de Defensa (Argentina)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["AR"], "dissemination_channels": ["website"], "event_date": "2026-10-19", "event_location": "Litoral and central-east, Argentina", "event_name": "Super El Niño 2026", "ew4all_pillars": [2, 3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Súper Niño 2026 en Argentina, EN VIVO: qué ciudades están en riesgo de inundación y cuándo llega el pico de la crecida", "outcome": "not_reported", "outcome_justification": "The snippet describes forecasts of intensity and activation of a contingency plan, but no outcomes are reported yet.", "relevant": true, "review": false, "summary_en": "The Servicio Meteorológico Nacional anticipated that the El Niño phenomenon will reach a ''strong or very strong'' intensity in central-east Argentina. The Ministry of Defence activated a contingency plan in the Litoral region in response to river flooding, and the live coverage focuses on which cities face flood risk and when the flood peak will arrive.", "summary_original": "El Servicio Meteorológico Nacional anticipó que el fenómeno alcanzará en el centro-este argentino una intensidad \"fuerte o muy fuerte\". El ministerio de Defensa activó el plan de contingencia en el Litoral por las crecidas de los ríos.", "title_en": "Super El Niño 2026 in Argentina, LIVE: which cities are at risk of flooding and when the flood peak arrives", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2616,'claude-haiku-5-5','2026-10-20T03:15:57Z',1,0.9,0,'{"actions_taken": ["Suspension of classes", "Preventive evacuations", "Technical roundtable coordination by Senapred and municipalities"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}, {"country": "CL", "name": "Ministerio del Interior de Chile", "type": "other_national_agency"}, {"country": "CL", "name": "Municipalities of Chile", "type": "other"}], "confidence": 0.9, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": null, "event_name": null, "ew4all_pillars": [3, 4], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Gobierno decreta suspensión de clases y evacuaciones preventivas ante ingreso de nuevo sistema frontal", "outcome": "not_reported", "outcome_justification": "The item reports warning-driven preparedness actions and a positive assessment of municipal response, but no measured outcome of the event is given.", "relevant": true, "review": false, "summary_en": "Chile''s Interior Undersecretary and the director of Senapred reported on a technical roundtable ahead of a new frontal system, describing a high national response from municipalities in implementing preparedness measures. The government decreed class suspensions and preventive evacuations in response to the incoming system.", "summary_original": "El subsecretario del Interior y la directora de Senapred entregaron un balance de la mesa técnica por el ingreso de un nuevo sistema frontal, destacando la alta respuesta de los municipios; el gobierno decretó suspensión de clases y evacuaciones preventivas.", "title_en": "Government decrees class suspensions and preventive evacuations ahead of new frontal system", "wmo_regions":