INSERT INTO "items" VALUES(259,'https://www.preventionweb.net/publication/documents-and-publications/un-declaration-sea-level-rise','https://preventionweb.net/publication/documents-and-publications/un-declaration-sea-level-rise','UN Declaration on Sea Level Rise','undeclarationonsealevelrise','preventionweb','PreventionWeb','en','2026-10-15T16:14:54Z','2026-10-16T15:26:23Z','This declaration urges strengthening of global action on sea level rise, emphasizing four pillars: science, adaptation, livelihoods, and legal issues, and calls for enhanced support and coordinated responses for vulnerable communities.',0.0,'filtered_out',NULL,NULL);
