INSERT INTO "items" VALUES(1454,'https://www.preventionweb.net/publication/documents-and-publications/disaster-risk-reduction-state-play-africa','https://preventionweb.net/publication/documents-and-publications/disaster-risk-reduction-state-play-africa','Disaster risk reduction state of play in Africa','disasterriskreductionstateofplayinafrica','preventionweb','PreventionWeb','en','2026-10-16T13:31:05Z','2026-10-18T03:04:05Z','This report assesses 2023–2026 disaster risk reduction in Africa since the 2015 Sendai Framework, finding climate hazards caused 90% of disasters and $133B losses, noting policy progress but highlighting persistent finance, data, and implementation gaps.',0.0,'filtered_out',NULL,NULL);
