INSERT INTO "stories" VALUES(1,'','other','2026-10-16T15:42:44Z','2026-10-16T15:35:36Z','2026-10-16','{"actions": ["Issuance of a daily bulletin with general forecast, adverse weather phenomena and fire danger forecast", "Forecast of cloud cover for observing the eclipse", "Interactive viewer accessible via www.trioeclipses.es", "Support to Civil Protection authorities for better management of the event"], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}, {"country": "ES", "name": "Protección Civil", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["social_media", "website"], "confidence": 0.8, "countries": [{"code": "ES", "name": "Spain"}], "event_date": "2026-10-16", "event_location": null, "event_name": null, "first_seen": "2026-10-16T15:35:36Z", "hazard": "other", "hazards": ["other"], "id": 1, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-16T15:35:36Z", "lead_time": "from Friday 7 August for the eclipse of 12 August", "outcome": "not_reported", "outcome_justification": "The item announces planned forecast services; no outcome is reported yet.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "AEMET noticias", "title": "El Gobierno de España emitirá a través de la Aemet una predicción meteorológica ...", "title_en": "The Spanish Government will issue, through AEMET, a special weather forecast for the eclipse", "url": "https://www.aemet.es/es/noticias/2026/08/prediccion_especial_eclipse_2026"}], "summaries_original": {"es": "La AEMET emitirá desde el 7 de agosto un boletín diario con predicción general, fenómenos adversos y peligro de incendios, además de la nubosidad prevista para el eclipse, con apoyo a Protección Civil."}, "summary_en": "AEMET will issue a daily bulletin from 7 August with general weather forecasts, adverse weather phenomena and fire danger forecasts ahead of the 12 August solar eclipse. Cloud cover forecasts will be available via an interactive viewer, and AEMET will support Civil Protection to manage the expected large influx of people.", "title": "The Spanish Government will issue, through AEMET, a special weather forecast for the eclipse", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(2,'severe_storm|GB|north-west scotland','severe_storm','2026-10-16T15:42:44Z','2026-10-16T15:30:44Z','2026-10-13','{"actions": ["Met Office issued a yellow wind warning for north-west Scotland for Wednesday"], "agencies": [{"country": "GB", "name": "Met Office", "type": "NMHS"}, {"country": "GB", "name": "BBC News", "type": "media"}], "agency_types": ["NMHS", "media"], "channels": ["website"], "confidence": 0.8, "countries": [{"code": "GB", "name": "United Kingdom"}], "event_date": "2026-10-13", "event_location": "North-west Scotland, United Kingdom", "event_name": null, "first_seen": "2026-10-16T15:30:44Z", "hazard": "severe_storm", "hazards": ["severe_storm"], "id": 2, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-16T15:30:44Z", "lead_time": "Warning covering Wednesday (approx. 1 day ahead of publication)", "outcome": "not_reported", "outcome_justification": "The item reports the warning being issued and forecast gusts of up to 70mph but gives no information on impacts or responses.", "pillars": [2, 3], "review": false, "sources": [{"language": "en", "published_at": "2026-10-13T23:55:49Z", "source_name": "BBC News Science & Environment", "title": "Gales and heavy rain to impact UK as yellow wind warning issued", "title_en": "Gales and heavy rain to impact UK as yellow wind warning issued", "url": "https://www.bbc.co.uk/weather/articles/cxvgdq0jj8d2o?at_medium=RSS&at_campaign=rss"}], "summaries_original": {}, "summary_en": "The UK Met Office has issued a yellow wind warning for north-west Scotland for Wednesday, with gusts of up to 70mph possible. The warning forms part of a forecast of gales and heavy rain across the UK. No impacts or responses are reported in the snippet.", "title": "Gales and heavy rain to impact UK as yellow wind warning issued", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(3,'multi_hazard|AO|eastern and southern africa','multi_hazard','2026-10-16T15:42:44Z','2026-10-16T15:26:20Z','2026-10-14','{"actions": [], "agencies": [{"country": null, "name": "World Food Programme (WFP)", "type": "international"}, {"country": null, "name": "World Health Organization", "type": "international"}], "agency_types": ["international"], "channels": ["website"], "confidence": 0.8, "countries": [{"code": "AO", "name": "Angola"}, {"code": "BI", "name": "Burundi"}, {"code": "CD", "name": "Democratic Republic of the Congo"}, {"code": "CG", "name": "Congo"}, {"code": "DJ", "name": "Djibouti"}, {"code": "ET", "name": "Ethiopia"}, {"code": "KE", "name": "Kenya"}, {"code": "LS", "name": "Lesotho"}, {"code": "MG", "name": "Madagascar"}, {"code": "MW", "name": "Malawi"}, {"code": "RW", "name": "Rwanda"}, {"code": "SD", "name": "Sudan"}, {"code": "SO", "name": "Somalia"}, {"code": "SS", "name": "South Sudan"}, {"code": "SZ", "name": "Eswatini"}, {"code": "TZ", "name": "Tanzania"}, {"code": "UG", "name": "Uganda"}, {"code": "ZM", "name": "Zambia"}, {"code": "ZW", "name": "Zimbabwe"}], "event_date": "2026-10-14", "event_location": "Eastern and Southern Africa", "event_name": null, "first_seen": "2026-10-16T15:26:20Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 3, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-16T15:26:20Z", "lead_time": "October to December 2026 outlook", "outcome": "not_reported", "outcome_justification": "The item is a seasonal outlook; no outcomes of warnings are reported.", "pillars": [2, 3], "review": false, "sources": [{"language": "en", "published_at": "2026-10-14T12:21:46Z", "source_name": "ReliefWeb - Updates", "title": "World: WFP Eastern and Southern Africa Seasonal Outlook: Eastern and Southern Africa Regional Office (ESARO) - October 2026", "title_en": "World: WFP Eastern and Southern Africa Seasonal Outlook: Eastern and Southern Africa Regional Office (ESARO) - October 2026", "url": "https://reliefweb.int/report/world/wfp-eastern-and-southern-africa-seasonal-outlook-eastern-and-southern-africa-regional-office-esaro-october-2026"}], "summaries_original": {}, "summary_en": "A WFP seasonal outlook for Eastern and Southern Africa forecasts above-normal rainfall and above-average temperatures for October to December 2026, with the strongest wet signal in southern Ethiopia, central and southern Somalia and Kenya, raising extreme rainfall and flood risks. The outlook is a forecast product intended to support anticipatory planning across the region.", "title": "World: WFP Eastern and Southern Africa Seasonal Outlook: Eastern and Southern Africa Regional Office (ESARO) - October 2026", "wmo_regions": ["I"]}');
INSERT INTO "stories" VALUES(4,'','flood','2026-10-16T15:42:44Z','2026-10-16T15:26:20Z','2026-10-14','{"actions": ["Activation of Simplified Early Action Protocol for floods", "Monitoring of seasonal and weekly forecasts"], "agencies": [{"country": "DJ", "name": "Djibouti Red Crescent National Society", "type": "NGO"}, {"country": null, "name": "ICPAC", "type": "international"}, {"country": null, "name": "International Federation of Red Cross and Red Crescent Societies", "type": "international"}], "agency_types": ["NGO", "international"], "channels": [], "confidence": 0.85, "countries": [{"code": "DJ", "name": "Djibouti"}], "event_date": "2026-10-14", "event_location": "Djibouti, Djibouti", "event_name": null, "first_seen": "2026-10-16T15:26:20Z", "hazard": "flood", "hazards": ["flood"], "id": 4, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-16T15:26:20Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes the protocol activation and forecasts but does not report outcomes of the early action or warnings.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-14T13:47:43Z", "source_name": "ReliefWeb - Updates", "title": "Djibouti | sEAP Flood - Simplified Early Action Protocol: Activation (MDRDJ009), 12/10/2026", "title_en": "Djibouti | sEAP Flood - Simplified Early Action Protocol: Activation (MDRDJ009), 12/10/2026", "url": "https://reliefweb.int/report/djibouti/djibouti-seap-flood-simplified-early-action-protocol-activation-mdrdj009-12102026"}], "summaries_original": {}, "summary_en": "The Djibouti Red Crescent Society activated its Simplified Early Action Protocol for floods after a seasonal forecast for October-December indicated El Niño-related rainfall impacts. ICPAC''s weekly forecast flagged potential rainfall for coastal zones including Djibouti, Tadjourah, Obock, Arta and parts of Ali Sabieh, and the National Society has been monitoring the situation.", "title": "Djibouti | sEAP Flood - Simplified Early Action Protocol: Activation (MDRDJ009), 12/10/2026", "wmo_regions": ["I"]}');
INSERT INTO "stories" VALUES(5,'flood|TH|bangkok','flood','2026-10-16T15:42:44Z','2026-10-16T15:26:23Z','2026-10-14','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.7, "countries": [{"code": "TH", "name": "Thailand"}], "event_date": "2026-10-14", "event_location": "Bangkok, Thailand", "event_name": null, "first_seen": "2026-10-16T15:26:23Z", "hazard": "flood", "hazards": ["flood"], "id": 5, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-16T15:26:23Z", "lead_time": null, "outcome": "negative", "outcome_justification": "Snippet indicates experts see gaps in flood defenses and an annual pattern of chaos and paralysis, implying shortcomings in preparedness and response, but no specific warning failures are detailed.", "pillars": [4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-14T14:17:16Z", "source_name": "PreventionWeb", "title": "Monsoon megacities under pressure: Hydro-political resilience and urban inundation risks in Bangkok", "title_en": "Monsoon megacities under pressure: Hydro-political resilience and urban inundation risks in Bangkok", "url": "https://www.preventionweb.net/news/monsoon-megacities-under-pressure-hydro-political-resilience-and-urban-inundation-risks"}, {"language": "en", "published_at": "2026-10-14T14:33:31Z", "source_name": "PreventionWeb", "title": "Sinking Bangkok: How historic floods exposed cracks in city’s disaster defenses", "title_en": "Sinking Bangkok: How historic floods exposed cracks in city''s disaster defenses", "url": "https://www.preventionweb.net/news/sinking-bangkok-how-historic-floods-exposed-cracks-citys-disaster-defenses"}], "summaries_original": {}, "summary_en": "An analysis piece argues that Bangkok''s flood defenses have major gaps exposed by historic flooding and that, without upgrades, the city will face recurring disruption as climate change intensifies. The snippet focuses on defense and response shortcomings rather than specific forecasts or warnings.", "title": "Sinking Bangkok: How historic floods exposed cracks in city''s disaster defenses", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(6,'','multi_hazard','2026-10-16T15:42:45Z','2026-10-16T15:26:23Z','2026-10-14','{"actions": ["Farmers adjusted labor hiring decisions based on forecast information"], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [{"code": "BD", "name": "Bangladesh"}, {"code": "ET", "name": "Ethiopia"}, {"code": "TZ", "name": "Tanzania"}, {"code": "UG", "name": "Uganda"}], "event_date": "2026-10-14", "event_location": null, "event_name": null, "first_seen": "2026-10-16T15:26:23Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 6, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-16T15:26:23Z", "lead_time": null, "outcome": "positive", "outcome_justification": "The study finds more accurate forecasts reduce crop losses and help farmers adjust labor hiring, especially during extreme weather events.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-14T14:18:29Z", "source_name": "PreventionWeb", "title": "Food security benefits of more accurate weather forecasts in the context of a changing climate", "title_en": "Food security benefits of more accurate weather forecasts in the context of a changing climate", "url": "https://www.preventionweb.net/publication/documents-and-publications/food-security-benefits-more-accurate-weather-forecasts"}], "summaries_original": {}, "summary_en": "A study using household survey and meteorological data from Ethiopia, Tanzania, Uganda and Bangladesh finds that more accurate weather forecasts reduce crop losses. The research indicates farmers use forecast information to adjust labor hiring, with the benefits most evident during extreme weather events. The item concerns the value of forecast accuracy for agricultural decision-making under climate change.", "title": "Food security benefits of more accurate weather forecasts in the context of a changing climate", "wmo_regions": ["I", "II"]}');
INSERT INTO "stories" VALUES(7,'','flash_flood','2026-10-16T15:42:45Z','2026-10-16T15:26:23Z','2026-10-14','{"actions": [], "agencies": [{"country": "IN", "name": "IIT Madras", "type": "other"}], "agency_types": ["other"], "channels": [], "confidence": 0.6, "countries": [{"code": "IN", "name": "India"}], "event_date": "2026-10-14", "event_location": null, "event_name": null, "first_seen": "2026-10-16T15:26:23Z", "hazard": "flash_flood", "hazards": ["flash_flood"], "id": 7, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-16T15:26:23Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item describes research findings on using air pollution data to improve rainfall and urban flood forecasting, with no reported warning outcomes.", "pillars": [2], "review": false, "sources": [{"language": "en", "published_at": "2026-10-14T14:30:34Z", "source_name": "PreventionWeb", "title": "IIT Madras-led international study finds atmospheric air pollution levels could aid in improving urban flood forecasts", "title_en": "IIT Madras-led international study finds atmospheric air pollution levels could aid in improving urban flood forecasts", "url": "https://www.preventionweb.net/news/iit-madras-led-international-study-finds-atmospheric-air-pollution-levels-could-aid-improving"}], "summaries_original": {}, "summary_en": "An international study led by IIT Madras reports that atmospheric air pollution levels could play a critical role in improving forecasts of rainfall and urban floods. The work relates to detection, monitoring and forecasting capability rather than a specific event or warning issued. The snippet provides limited detail on methods or implementation.", "title": "IIT Madras-led international study finds atmospheric air pollution levels could aid in improving urban flood forecasts", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(8,'named|kumamoto earthquake','earthquake','2026-10-16T15:42:45Z','2026-10-16T15:26:23Z','2026-10-14','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.6, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-14", "event_location": "Kumamoto, Japan", "event_name": "2026 Kumamoto earthquake", "first_seen": "2026-10-16T15:26:23Z", "hazard": "earthquake", "hazards": ["earthquake"], "id": 8, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-16T15:26:23Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes an information vacuum after the earthquake caused by damaged roads and failed communications, but does not report any warning outcomes.", "pillars": [4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-14T14:32:11Z", "source_name": "PreventionWeb", "title": "2026 Kumamoto earthquake: The problem is not resource shortage but a lack of accessibility", "title_en": "2026 Kumamoto earthquake: The problem is not resource shortage but a lack of accessibility", "url": "https://www.preventionweb.net/news/2026-kumamoto-earthquake-problem-not-resource-shortage-lack-accessibility"}], "summaries_original": {}, "summary_en": "The article argues that after the 2026 Kumamoto earthquake the main problem was not a shortage of resources but a lack of accessibility. Damaged roads and failed communications left affected areas in an information vacuum, so onsite surveys could not quickly establish what help was needed and where. The item is relevant mainly for the response and situational-information aspects of early warning and emergency communication.", "title": "2026 Kumamoto earthquake: The problem is not resource shortage but a lack of accessibility", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(9,'','flood','2026-10-16T15:42:45Z','2026-10-16T15:26:23Z','2026-10-14','{"actions": ["Livelihood support for affected households"], "agencies": [{"country": null, "name": "Asian Development Bank", "type": "international"}], "agency_types": ["international"], "channels": [], "confidence": 0.8, "countries": [{"code": "ID", "name": "Indonesia"}], "event_date": "2026-10-14", "event_location": "Indonesia", "event_name": null, "first_seen": "2026-10-16T15:26:23Z", "hazard": "flood", "hazards": ["flood"], "id": 9, "impacts": {"economic_losses": "USD 5.8 billion (estimated, 2010-2025)"}, "languages": ["en"], "last_updated": "2026-10-16T15:26:23Z", "lead_time": "up to nine hours", "outcome": "not_reported", "outcome_justification": "The snippet cites ADB-backed forecasting that warns communities up to nine hours ahead but does not report measured outcomes of those warnings.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-14T14:37:21Z", "source_name": "PreventionWeb", "title": "Saving lives, restoring livelihoods: building resilient communities in Indonesia", "title_en": "Saving lives, restoring livelihoods: building resilient communities in Indonesia", "url": "https://www.preventionweb.net/news/saving-lives-restoring-livelihoods-building-resilient-communities-indonesia"}], "summaries_original": {}, "summary_en": "Between 2010 and 2025 floods in Indonesia caused more than 1,700 deaths and an estimated USD 5.8 billion in losses. ADB-backed forecasting systems now warn communities up to nine hours ahead, alongside livelihood support for affected households. The snippet does not report outcomes of these warnings.", "title": "Saving lives, restoring livelihoods: building resilient communities in Indonesia", "wmo_regions": ["II", "V"]}');
INSERT INTO "stories" VALUES(10,'flood|CL|santiago metropolitan region','heavy_rain','2026-10-16T15:42:45Z','2026-10-20T03:14:44Z','2026-10-14','{"actions": ["Declaration of a Red Alert for the Metropolitan Region", "Suspension of classes in more than 100 establishments", "Closure of Metro stations", "Government declared preventive emergency in O''Higgins, Maule and Metropolitan Region until 23 October", "Red alert issued for ten pre-Andean communes of Santiago", "Flood-risk alerts issued for five northern and central regions", "Declaration of red alert for the Metropolitan Region"], "agencies": [{"country": "CL", "name": "Government of Chile", "type": "other_national_agency"}, {"country": "CL", "name": "Government of Chile (Ministry of Interior/Emergency authorities, minister Ximena Rincón)", "type": "other_national_agency"}, {"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.85, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-14", "event_location": "Metropolitan Region, Chile", "event_name": null, "first_seen": "2026-10-16T15:35:36Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 10, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-20T03:14:44Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports the red alert being lifted and the disruptions caused, but does not state whether the warning led to lives saved or reduced losses, nor whether it was received or acted upon.", "pillars": [3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-14T15:35:32Z", "source_name": "cooperativa.cl", "title": "Alerta roja para la Región Metropolitana ante fuertes lluvias - Cooperativa.cl", "title_en": "Red alert for the Metropolitan Region due to heavy rain", "url": "https://cooperativa.cl/noticias/pais/tiempo/alerta-roja-para-la-region-metropolitana-ante-fuertes-lluvias/2026-10-13/165657.html"}, {"language": "es", "published_at": "2026-10-15T07:46:13Z", "source_name": "radioagricultura.cl", "title": "Ministra Rincón confirma fin de la Alerta Roja tras las fuertes lluvias en la Región Metropolitana", "title_en": "Minister Rincón confirms end of Red Alert after heavy rains in the Metropolitan Region", "url": "https://www.radioagricultura.cl/noticias/nacional/ministra-rincon-anuncia-fin-de-la-alerta-roja-por-las-fuertes-lluvias-en-la-region-metropolitanas_20261014/"}, {"language": "es", "published_at": "2026-10-20T03:14:37Z", "source_name": "abc.com.py", "title": "Chile se prepara para un nuevo temporal que podría dejar inundaciones - Mundo - ABC Color", "title_en": "Chile prepares for a new storm that could bring floods", "url": "https://www.abc.com.py/internacionales/2026/10/19/chile-se-prepara-para-un-nuevo-temporal-que-podria-dejar-inundaciones/"}], "summaries_original": {"es": "La ministra Ximena Rincón confirmó el fin de la Alerta Roja por fuertes lluvias que causaron anegamientos, cierres del Metro y suspensión de clases en más de 100 establecimientos en la Región Metropolitana."}, "summary_en": "Chile''s government confirmed the end of a Red Alert declared for the Metropolitan Region due to heavy rains that caused flooding, Metro station closures and suspension of classes in over 100 schools. The minister warned there were no certain indicators that the bad weather would end, so the alert status reflects an ongoing hazard assessment.", "title": "Minister Rincón confirms end of Red Alert after heavy rains in the Metropolitan Region", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(11,'multi_hazard|CL|region metropolitana','multi_hazard','2026-10-16T15:42:45Z','2026-10-19T03:11:12Z','2026-10-14','{"actions": ["Red alert declared for the Metropolitan Region", "Evacuations in Talagante"], "agencies": [{"country": null, "name": "UN Office for the Coordination of Humanitarian Affairs", "type": "international"}, {"country": null, "name": "UN Office for the Coordination of Humanitarian Affairs (OCHA)", "type": "international"}, {"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["international", "other_national_agency"], "channels": ["other"], "confidence": 0.85, "countries": [{"code": "CL", "name": "Chile"}, {"code": "GU", "name": "Guam"}, {"code": "HT", "name": "Haiti"}, {"code": "MX", "name": "Mexico"}, {"code": "PA", "name": "Panama"}], "event_date": "2026-10-14", "event_location": "Michoacán and Colima, Mexico; Chile; Panama", "event_name": null, "first_seen": "2026-10-16T15:35:36Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 11, "impacts": {"affected": 34000, "evacuated": 3600}, "languages": ["en", "es"], "last_updated": "2026-10-19T03:11:12Z", "lead_time": "Forecast to intensify and pass near Michoacán and Colima this weekend", "outcome": "not_reported", "outcome_justification": "The snippet reports a forecast of Hurricane Trudy''s intensification and impacts from storms, earthquake and power outages, but does not describe warning dissemination outcomes.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-14T15:35:32Z", "source_name": "lahora.gt", "title": "Declaran alerta roja en Santiago de Chile por tormentas, granizo e inundaciones - La Hora", "title_en": "Red alert declared in Santiago de Chile due to storms, hail and flooding", "url": "https://lahora.gt/internacionales/hbeteta/2026/10/13/declaran-alerta-roja-en-santiago-de-chile-por-tormentas-granizo-e-inundaciones-now/"}, {"language": "en", "published_at": "2026-10-16T20:05:26Z", "source_name": "ReliefWeb - Updates", "title": "Panama: Latin America & The Caribbean Weekly Situation Update as of 16 October 2026", "title_en": "Panama: Latin America & The Caribbean Weekly Situation Update as of 16 October 2026", "url": "https://reliefweb.int/report/panama/latin-america-caribbean-weekly-situation-update-16-october-2026"}, {"language": "en", "published_at": "2026-10-16T20:05:26Z", "source_name": "ReliefWeb - Updates", "title": "Mexico: Latin America & The Caribbean Weekly Situation Update as of 16 October 2026", "title_en": "Mexico: Latin America & The Caribbean Weekly Situation Update as of 16 October 2026", "url": "https://reliefweb.int/report/mexico/latin-america-caribbean-weekly-situation-update-16-october-2026"}, {"language": "es", "published_at": "2026-10-16T20:11:07Z", "source_name": "ReliefWeb - Updates", "title": "Panama: Latinoamérica y El Caribe Resumen de Situación Semanal al 16 de octubre 2026", "title_en": "Panama: Latin America and the Caribbean Weekly Situation Summary as of 16 October 2026", "url": "https://reliefweb.int/report/panama/latinoamerica-y-el-caribe-resumen-de-situacion-semanal-al-16-de-octubre-2026"}, {"language": "es", "published_at": "2026-10-16T20:11:07Z", "source_name": "ReliefWeb - Updates", "title": "Mexico: Latinoamérica y El Caribe Resumen de Situación Semanal al 16 de octubre 2026", "title_en": "Mexico: Latin America and the Caribbean Weekly Situation Summary as of 16 October 2026", "url": "https://reliefweb.int/report/mexico/latinoamerica-y-el-caribe-resumen-de-situacion-semanal-al-16-de-octubre-2026"}, {"language": "en", "published_at": "2026-10-17T12:45:00Z", "source_name": "cnbc.com", "title": "Hurricane Trudy heads toward Mexico as Typhoon Champi threatens Guam", "title_en": "Hurricane Trudy heads toward Mexico as Typhoon Champi threatens Guam", "url": "https://www.cnbc.com/2026/10/17/hurricane-trudy-mexico-typhoon-champi-guam.html"}, {"language": "en", "published_at": "2026-10-17T16:30:00Z", "source_name": "nvdaily.com", "title": "Hurricane Trudy approaches Mexico as Typhoon Champi threatens Guam", "title_en": "Hurricane Trudy approaches Mexico as Typhoon Champi threatens Guam", "url": "https://www.nvdaily.com/associated_press_national/hurricane-trudy-approaches-mexico-as-typhoon-champi-threatens-guam/article_3f22c69a-fc48-50bb-afeb-cb7bf00703d8.html"}], "summaries_original": {"es": "Resumen semanal de OCHA sobre Latinoamérica y el Caribe que informa sobre la previsión de que la tormenta Trudy se intensifique hasta huracán de categoría 4 frente a las costas de Michoacán y Colima, México, además de 36.000 personas sin electricidad en Chile y 3.600 en albergues tras un terremoto de magnitud 7,5 en Panamá."}, "summary_en": "A UN OCHA weekly summary for Latin America and the Caribbean reports a forecast that Tropical Storm Trudy will strengthen into a Category 4 hurricane before passing off the coasts of Michoacán and Colima, Mexico, this weekend. It also notes 36,000 people without electricity in Chile after bad weather and 3,600 people in shelters after a magnitude 7.5 earthquake in Panama, with 4,000 homes damaged.", "title": "Mexico: Latin America and the Caribbean Weekly Situation Summary as of 16 October 2026", "wmo_regions": ["III", "IV", "V"]}');
INSERT INTO "stories" VALUES(12,'flood|PE|cordillera blanca','flash_flood','2026-10-16T15:42:45Z','2026-10-16T15:35:57Z','2026-10-14','{"actions": ["Installation of 32 alert points with cameras and sensors in four ravines of the Cordillera Blanca", "System to be operated from the COER Áncash to support emergency response"], "agencies": [{"country": "PE", "name": "Instituto Geofísico del Perú (IGP)", "type": "NMHS"}, {"country": "PE", "name": "COER Áncash", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": [], "confidence": 0.9, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-14", "event_location": "Cordillera Blanca, Áncash, Peru", "event_name": null, "first_seen": "2026-10-16T15:35:57Z", "hazard": "flash_flood", "hazards": ["flash_flood"], "id": 12, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-16T15:35:57Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item announces planned installation of an early warning system; no outcome has yet been reported.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-10-14T18:23:59Z", "source_name": "La República (Perú) sociedad", "title": "IGP instalará 32 puntos de alerta para prevenir aluviones en cuatro quebradas de la Cordillera Blanca en Áncash", "title_en": "IGP will install 32 alert points to prevent avalanches/floods in four ravines of the Cordillera Blanca in Áncash", "url": "https://larepublica.pe/sociedad/2026/10/14/igp-instalara-32-puntos-de-alerta-para-prevenir-aluviones-en-cuatro-quebradas-de-la-cordillera-blanca-en-ancash-1270178"}], "summaries_original": {"es": "El IGP instalará 32 puntos de alerta con cámaras y sensores en cuatro quebradas de la Cordillera Blanca, Áncash, para prevenir aluviones. El sistema operará desde el COER Áncash y fortalecerá la alerta temprana en zonas de riesgo."}, "summary_en": "Peru''s Geophysical Institute (IGP) will install 32 alert points with cameras and sensors in four ravines of the Cordillera Blanca in Áncash to prevent avalanches and floods. The system will operate from the regional emergency operations centre (COER Áncash) to strengthen early warning in risk zones.", "title": "IGP will install 32 alert points to prevent avalanches/floods in four ravines of the Cordillera Blanca in Áncash", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(13,'','other','2026-10-16T15:42:45Z','2026-10-16T15:30:35Z','2026-10-14','{"actions": [], "agencies": [{"country": "US", "name": "NOAA", "type": "NMHS"}, {"country": "US", "name": "National Weather Service", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": ["website"], "confidence": 0.6, "countries": [{"code": "US", "name": "United States"}], "event_date": "2026-10-14", "event_location": "United States", "event_name": null, "first_seen": "2026-10-16T15:30:35Z", "hazard": "other", "hazards": ["other"], "id": 13, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-16T15:30:35Z", "lead_time": "December 2026 to February 2027 (winter season outlook)", "outcome": "not_reported", "outcome_justification": "The item is a seasonal outlook describing expected El Nino-driven temperature and precipitation patterns; no realised outcomes or warning impacts are reported.", "pillars": [2], "review": false, "sources": [{"language": "en", "published_at": "2026-10-14T19:40:37Z", "source_name": "NOAA / US National Weather Service news", "title": "El Nino looms large over U.S. Winter Outlook", "title_en": "El Nino looms large over U.S. Winter Outlook", "url": "https://www.noaa.gov/news-release/el-nino-looms-large-over-us-winter-outlook"}], "summaries_original": {}, "summary_en": "NOAA released its U.S. Winter Outlook for December 2026 to February 2027, forecasting warmer-than-average conditions across the northern U.S. and wetter-than-average conditions across the southern U.S. and Eastern Seaboard due to El Nino. The outlook is a seasonal forecast product that supports forecasting and advance communication of likely winter conditions.", "title": "El Nino looms large over U.S. Winter Outlook", "wmo_regions": ["IV"]}');
INSERT INTO "stories" VALUES(14,'','multi_hazard','2026-10-16T15:42:47Z','2026-10-16T15:26:20Z','2026-10-14','{"actions": [], "agencies": [{"country": null, "name": "Famine Early Warning System Network (FEWS NET)", "type": "international"}], "agency_types": ["international"], "channels": ["website"], "confidence": 0.8, "countries": [], "event_date": "2026-10-14", "event_location": null, "event_name": null, "first_seen": "2026-10-16T15:26:20Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 14, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-16T15:26:20Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The summary reports monitoring and forecasts of abnormal heat, flooding and dryness but gives no information on warning dissemination or actions taken.", "pillars": [2], "review": false, "sources": [{"language": "en", "published_at": "2026-10-14T20:03:09Z", "source_name": "ReliefWeb - Updates", "title": "World: Global Weather Hazards Summary, October 15, 2026 – October 21, 2026", "title_en": "World: Global Weather Hazards Summary, October 15, 2026 – October 21, 2026", "url": "https://reliefweb.int/report/world/global-weather-hazards-summary-october-15-2026-october-21-2026"}], "summaries_original": {}, "summary_en": "FEWS NET''s weekly global weather hazards summary reports El Niño strengthening and persistent abnormal dryness and heat across parts of Africa, Central Asia, Central America, Hispaniola and northern South America. It forecasts abnormal heat in the eastern Sahel and Eastern Africa, high flood risks in the Horn of Africa, and ongoing inundation in the Sudd wetlands of South Sudan. The item focuses on hazard monitoring and forecasting rather than warning dissemination.", "title": "World: Global Weather Hazards Summary, October 15, 2026 – October 21, 2026", "wmo_regions": ["I", "II", "IV", "VI"]}');
INSERT INTO "stories" VALUES(15,'volcanic|CL|nevados de chillan','volcanic','2026-10-16T15:42:47Z','2026-10-16T15:26:22Z','2026-10-15','{"actions": ["Maintenance of technical alert at Yellow level by OVDAS/SERNAGEOMIN", "Issuance of a Special Volcanic Activity Report (REAV) on 14 October", "Monitoring by stations installed near the Nevados de Chillán volcanic complex"], "agencies": [{"country": "CL", "name": "Cruz Roja Chilena", "type": "NGO"}, {"country": null, "name": "International Federation of Red Cross and Red Crescent Societies", "type": "international"}, {"country": "CL", "name": "OVDAS (Observatorio Volcánico de los Andes del Sur)", "type": "other_national_agency"}, {"country": "CL", "name": "SERNAGEOMIN", "type": "other_national_agency"}], "agency_types": ["NGO", "international", "other_national_agency"], "channels": [], "confidence": 0.85, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-15", "event_location": "Nevados de Chillán, Chile", "event_name": null, "first_seen": "2026-10-16T15:26:22Z", "hazard": "volcanic", "hazards": ["volcanic"], "id": 15, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-16T15:26:22Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet does not report the effects of the warnings or whether communities acted on them.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-10-15T00:37:30Z", "source_name": "ReliefWeb - Updates", "title": "Chile: CHL: Erupción volcánica - 07-2026 - Actualización Erupción Volcánica #2 (2026-10-14)", "title_en": "Chile: CHL: Volcanic Eruption - 07-2026 - Volcanic Eruption Update #2 (2026-10-14)", "url": "https://reliefweb.int/report/chile/chl-erupcion-volcanica-07-2026-actualizacion-erupcion-volcanica-2-2026-10-14"}], "summaries_original": {"es": "Según el OVDAS del SERNAGEOMIN, el Complejo Volcánico Nevados de Chillán mantiene la alerta técnica en nivel Amarillo, con un Reporte Especial de Actividad Volcánica (REAV) emitido el 14 de octubre basado en estaciones de monitoreo cercanas al complejo."}, "summary_en": "SERNAGEOMIN''s volcano observatory OVDAS kept the Nevados de Chillán volcanic complex at Yellow technical alert and issued a Special Volcanic Activity Report on 14 October 2026, based on monitoring stations near the volcano. The Chilean Red Cross and IFRC shared the update via ReliefWeb.", "title": "Chile: CHL: Volcanic Eruption - 07-2026 - Volcanic Eruption Update #2 (2026-10-14)", "wmo_regions": ["III"]}');
