INSERT INTO "stories" VALUES(44,'named|no 30','tropical_cyclone','2026-10-17T07:47:30Z','2026-10-20T03:08:48Z','2026-10-17','{"actions": ["JMA issued forecast of intensification into a very strong typhoon", "JMA called on the public to stay informed about future information", "Japan Meteorological Agency called on residents to prepare early", "Rough seas and strengthening winds forecast from the 21st in Okinawa Prefecture", "JMA forecasting typhoon track and advising the public to follow further information"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}, {"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "NHK", "type": "media"}], "agency_types": ["NMHS", "media"], "channels": ["other"], "confidence": 0.93, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-17", "event_location": null, "event_name": "Typhoon No. 30 (2026)", "first_seen": "2026-10-17T07:39:30Z", "hazard": "tropical_cyclone", "hazards": ["tropical_cyclone"], "id": 44, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-20T03:08:48Z", "lead_time": "Next week''s track forecast (approx. 5-7 days ahead, as implied)", "outcome": "not_reported", "outcome_justification": "The item reports a forecast and advisory only; no impacts or outcomes of the warning are described yet.", "pillars": [2, 3], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-17T01:34:00Z", "source_name": "NHK ニュース 主要", "title": "台風30号 非常に強い勢力に発達する見込み 今後の情報に注意", "title_en": "Typhoon No. 30 expected to develop into a very strong typhoon; public urged to stay informed", "url": "https://news.web.nhk/newsweb/na/nd-20261017de60802"}, {"language": "ja", "published_at": "2026-10-18T01:52:44Z", "source_name": "NHK ニュース 主要", "title": "台風30号 22日ごろ沖縄の南海上に達する予想 今後の情報に注意", "title_en": "Typhoon No. 30 expected to reach waters south of Okinawa around the 22nd; watch for further information", "url": "https://news.web.nhk/newsweb/na/nd-20261018de61065"}, {"language": "ja", "published_at": "2026-10-20T02:53:18Z", "source_name": "NHK ニュース 主要", "title": "台風30号 23日から沖縄の先島諸島に接近見込み 最新情報確認を", "title_en": "Typhoon No. 30 expected to approach Sakishima Islands, Okinawa from the 23rd; check latest information", "url": "https://news.web.nhk/newsweb/na/nd-20261020de61985"}], "summaries_original": {"ja": "強い台風30号は、日本のはるか南東の海上を西寄りに進んでおり、今後非常に強い勢力に発達する見込みです。来週の進路予想には幅があり、気象庁は今後の情報に注意するよう呼びかけています。"}, "summary_en": "Typhoon No. 30 is moving westward over the sea far southeast of Japan and is forecast to intensify into a very strong typhoon. The track forecast for next week has a wide range of uncertainty, and the Japan Meteorological Agency has urged the public to keep following the latest information.", "title": "Typhoon No. 30 expected to develop into a very strong typhoon; public urged to stay informed", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(45,'tropical_cyclone|CK|suwarrow','tropical_cyclone','2026-10-17T07:47:31Z','2026-10-17T09:45:38Z','2026-10-16','{"actions": ["Residents urged to prepare for damaging winds and heavy swells"], "agencies": [{"country": "CK", "name": "Cook Islands Meteorological Service", "type": "NMHS"}, {"country": "US", "name": "U.S. Embassy", "type": "other"}], "agency_types": ["NMHS", "other"], "channels": ["website"], "confidence": 0.9, "countries": [{"code": "CK", "name": "Cook Islands"}], "event_date": "2026-10-16", "event_location": "Suwarrow, Cook Islands", "event_name": null, "first_seen": "2026-10-17T07:39:16Z", "hazard": "tropical_cyclone", "hazards": ["tropical_cyclone"], "id": 45, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-17T09:45:38Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "Snippet reports a cyclone warning and preparedness call but gives no information on how the event unfolded or its results.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-16T21:30:00Z", "source_name": "cookislandsnews.com", "title": "Cook Islands urged to prepare as tropical cyclone warning issued for Suwarrow", "title_en": "Cook Islands urged to prepare as tropical cyclone warning issued for Suwarrow", "url": "https://www.cookislandsnews.com/internal/national/outer-islands/weather/cook-islands-urged-to-prepare-as-tropical-cyclone-warning-issued-for-suwarrow/"}, {"language": "en", "published_at": "2026-10-17T07:39:10Z", "source_name": "nz.usembassy.gov", "title": "Weather Alert: Cyclone Warning for Cook Islands", "title_en": "Weather Alert: Cyclone Warning for Cook Islands", "url": "https://nz.usembassy.gov/weather-alert-cyclone-warning-for-cook-islands-october-16-17-2026/"}], "summaries_original": {}, "summary_en": "A tropical depression was forecast to strengthen into a Category 1 cyclone near Suwarrow, prompting severe weather warnings across the Cook Islands. Officials urged residents to prepare for damaging winds and heavy swells. The snippet does not specify the warning channels or the outcome.", "title": "Cook Islands urged to prepare as tropical cyclone warning issued for Suwarrow", "wmo_regions": ["V"]}');
INSERT INTO "stories" VALUES(46,'multi_hazard|JP|fukushima','multi_hazard','2026-10-17T07:47:31Z','2026-10-17T07:42:19Z','2026-10-17','{"actions": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}, {"country": "JP", "name": "Fukushima Television", "type": "media"}], "agency_types": ["NMHS", "media"], "channels": [], "confidence": 0.85, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-17", "event_location": "Fukushima, Japan", "event_name": null, "first_seen": "2026-10-17T07:42:19Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 46, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-17T07:42:19Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes changes to the warning system and municipal difficulties in responding, but reports no specific event outcome.", "pillars": [2, 3], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-17T07:42:14Z", "source_name": "news.yahoo.co.jp", "title": "防災気象情報が新運用から5カ月 河川警報と線状降水帯予測に新制度 自治体は対応に課題（福島テレビ） - Yahoo!ニュース", "title_en": "Five months after new disaster weather information operations began: new river warning and linear rainband forecast system; municipalities face challenges in responding (Fukushima TV)", "url": "https://news.yahoo.co.jp/articles/8de08cad664498b8c930f2473de2c282f54a92d8"}], "summaries_original": {"ja": "2026年5月から防災気象情報の運用が変わり、避難の判断に使われる「レベル3」「レベル4」などの新しい呼びかけが始まった。河川の警報対象や線状降水帯の直前予測など仕組みが大きく変わる中、自治体では対応に悩む声も出ている。"}, "summary_en": "Since May 2026, Japan''s disaster weather information has been operated under a new system, introducing evacuation-level calls such as Level 3 and Level 4, river warning targets, and short-term forecasts of linear rainbands. Municipalities report difficulties in deciding how to respond to the changes.", "title": "Five months after new disaster weather information operations began: new river warning and linear rainband forecast system; municipalities face challenges in responding (Fukushima TV)", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(47,'severe_storm|CL|region metropolitana','severe_storm','2026-10-17T07:47:31Z','2026-10-17T07:46:21Z','2026-10-17','{"actions": ["Senapred declared a Preventive Early Alert for the Metropolitan Region", "DMC issued an advisory for probable thunderstorms in seven regions between 19 and 20 October"], "agencies": [{"country": "CL", "name": "Dirección Meteorológica de Chile (DMC)", "type": "NMHS"}, {"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other"], "confidence": 0.95, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-17", "event_location": "Región Metropolitana, Chile", "event_name": null, "first_seen": "2026-10-17T07:46:21Z", "hazard": "severe_storm", "hazards": ["severe_storm"], "id": 47, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-17T07:46:21Z", "lead_time": "about 2 days before the frontal system arrives (Monday 19 to Wednesday 21 October)", "outcome": "not_reported", "outcome_justification": "The item only reports forecasts and alerts issued; no observed outcomes are given.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-17T07:46:13Z", "source_name": "meganoticias.cl", "title": "Alerta Temprana Preventiva para la Región Metropolitana: Se esperan tormentas eléctricas con granizos - Meganoticias", "title_en": "Preventive Early Alert for the Metropolitan Region: Thunderstorms with Hail Expected", "url": "https://www.meganoticias.cl/nacional/534134-alerta-temprana-preventiva-region-metropolitana-sistema-frontal-lluvia-octubre-16-10-2026.html"}], "summaries_original": {"es": "Senapred declaró Alerta Temprana Preventiva para la Región Metropolitana por el pronóstico de un nuevo sistema frontal que ingresaría el lunes y se mantendría activo hasta el miércoles. La DMC emitió un aviso por probables tormentas eléctricas en siete regiones entre el lunes 19 y el martes 20 de octubre."}, "summary_en": "Senapred declared a Preventive Early Alert for the Santiago Metropolitan Region ahead of a new frontal system expected Monday and active until Wednesday, bringing possible thunderstorms with hail. The Dirección Meteorológica de Chile issued an advisory for probable thunderstorms in seven regions between 19 and 20 October.", "title": "Preventive Early Alert for the Metropolitan Region: Thunderstorms with Hail Expected", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(48,'multi_hazard|CL|metropolitan region','multi_hazard','2026-10-17T07:47:31Z','2026-10-20T03:14:59Z','2026-10-17','{"actions": ["Senapred declared Preventive Early Alert for the Metropolitan Region in coordination with the regional presidential delegation", "Suspension of classes", "Preventive evacuations", "Technical roundtable coordination by Senapred and municipalities", "Suspension of classes in 10 communes of the Metropolitan Region under red alert", "Authorities placed on alert over risk of flash floods, floods and electrical storms"], "agencies": [{"country": "CL", "name": "Dirección Meteorológica de Chile (DMC)", "type": "NMHS"}, {"country": "CL", "name": "BioBioChile", "type": "media"}, {"country": "CL", "name": "TVN meteorologists", "type": "media"}, {"country": "CL", "name": "Municipalities of Chile", "type": "other"}, {"country": "CL", "name": "Delegación Presidencial Regional Metropolitana", "type": "other_national_agency"}, {"country": "CL", "name": "Government of Chile (education authorities)", "type": "other_national_agency"}, {"country": "CL", "name": "Ministerio del Interior de Chile", "type": "other_national_agency"}, {"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["NMHS", "media", "other", "other_national_agency"], "channels": ["other", "tv"], "confidence": 0.95, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-17", "event_location": "Metropolitan Region, Chile", "event_name": null, "first_seen": "2026-10-17T07:46:21Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 48, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-20T03:14:59Z", "lead_time": "Warning issued 2-3 days before forecast precipitation (Tuesday 20 to Wednesday 21 October)", "outcome": "not_reported", "outcome_justification": "The item reports the forecast and preventive alert declaration only; no outcome of the event is given.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-17T07:46:13Z", "source_name": "cnnchile.com", "title": "Pronóstico de lluvias, granizo y tormentas eléctricas en Santiago: Senapred declara Alerta Temprana Preventiva en la Región Metropolitana", "title_en": "Forecast of rain, hail and thunderstorms in Santiago: Senapred declares Preventive Early Alert in the Metropolitan Region", "url": "https://www.cnnchile.com/pais/pronostico-de-lluvias-granizo-y-tormentas-electricas-en-santiago-senapred-declara-alerta-temprana-preventiva-en-la-region-metropolitana/"}, {"language": "es", "published_at": "2026-10-19T00:26:51Z", "source_name": "BioBioChile nacional", "title": "Suspenden clases en 10 comunas de la RM para este martes por alerta roja ante nuevo sistema frontal", "title_en": "Classes suspended in 10 communes of the Metropolitan Region for Tuesday due to red alert ahead of new frontal system", "url": "https://www.biobiochile.cl/noticias/nacional/region-metropolitana/2026/10/18/suspenden-clases-en-10-comunas-de-la-rm-para-este-martes-por-alerta-roja-ante-nuevo-sistema-frontal.shtml"}, {"language": "es", "published_at": "2026-10-20T00:32:29Z", "source_name": "BioBioChile nacional", "title": "Expertos explican \"tridente meteorológico\" que podría desatar \"tormenta perfecta\" en la zona central", "title_en": "Experts explain \"meteorological trident\" that could trigger \"perfect storm\" in central zone", "url": "https://www.biobiochile.cl/noticias/ciencia-y-tecnologia/ciencia/2026/10/19/expertos-explican-tridente-meteorologico-que-podria-desatar-tormenta-perfecta-en-la-zona-central.shtml"}, {"language": "es", "published_at": "2026-10-20T01:00:12Z", "source_name": "BioBioChile nacional", "title": "Gobierno decreta suspensión de clases y evacuaciones preventivas ante ingreso de nuevo sistema frontal", "title_en": "Government decrees class suspensions and preventive evacuations ahead of new frontal system", "url": "https://www.biobiochile.cl/noticias/nacional/chile/2026/10/19/gobierno-decreta-suspension-de-clases-y-evacuaciones-preventivas-ante-ingreso-de-nuevo-sistema-frontal.shtml"}], "summaries_original": {"es": "Senapred declaró Alerta Temprana Preventiva para la Región Metropolitana por el pronóstico de lluvias, granizo y tormentas eléctricas previstas entre el martes 20 y el miércoles 21 de octubre, en coordinación con la Delegación Presidencial. La DMC emitió un aviso por precipitaciones normales a moderadas."}, "summary_en": "Chile''s national emergency service Senapred declared a Preventive Early Alert for the Metropolitan Region based on a DMC forecast of normal to moderate rain, hail and thunderstorms expected between 20 and 21 October. The alert was declared in coordination with the regional presidential delegation ahead of the forecast event.", "title": "Forecast of rain, hail and thunderstorms in Santiago: Senapred declares Preventive Early Alert in the Metropolitan Region", "wmo_regions": ["III"]}');
