INSERT INTO "stories" VALUES(72,'flood|ES|barcelona','heavy_rain','2026-10-20T03:20:00Z','2026-10-20T03:14:37Z','2026-10-18','{"actions": ["Suspension of classes in Mallorca, Eivissa and Formentera", "Deployment of the UME", "Request that the population stay at home", "Mobilisation of the UME", "Suspension of classes in the Balearic Islands"], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}, {"country": "ES", "name": "Government of Spain", "type": "other_national_agency"}, {"country": "ES", "name": "UME (Unidad Militar de Emergencias)", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["cell_broadcast", "other"], "confidence": 0.9, "countries": [{"code": "ES", "name": "Spain"}], "event_date": "2026-10-18", "event_location": "Valencia, Alicante, Ibiza and Formentera, Spain", "event_name": "DANA Adam", "first_seen": "2026-10-20T03:08:34Z", "hazard": "heavy_rain", "hazards": ["flood", "heavy_rain"], "id": 72, "impacts": {"deaths": 1}, "languages": ["en", "es"], "last_updated": "2026-10-20T03:14:37Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports a red alert and flood risk but gives no information on impacts or the effectiveness of the warnings.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-18T16:45:00Z", "source_name": "english.aawsat.com", "title": "One Dead Near Barcelona as Torrential Rain Sparks Floods in Spain", "title_en": "One Dead Near Barcelona as Torrential Rain Sparks Floods in Spain", "url": "https://english.aawsat.com/world/5330918-one-dead-near-barcelona-torrential-rain-sparks-floods-spain"}, {"language": "es", "published_at": "2026-10-18T18:15:00Z", "source_name": "elimparcial.es", "title": "Un fallecido y alerta roja en Andalucía, Murcia, Comunidad Valenciana, Cataluña y Baleares por las lluvias torrenciales", "title_en": "One dead and red alert in Andalusia, Murcia, Valencian Community, Catalonia and the Balearic Islands due to torrential rain", "url": "https://www.elimparcial.es/noticia/303036/sociedad/un-fallecido-y-alerta-roja-enandalucia-murcia-comunidad-valenciana-cataluna-y-balearespor-las-lluvias-torrenciales.html"}, {"language": "es", "published_at": "2026-10-18T18:15:00Z", "source_name": "elimparcial.es", "title": "Andalucía, Murcia, Barcelona y la Comunidad Valenciana, en alerta roja por las lluvias", "title_en": "Andalusia, Murcia, Barcelona and the Valencian Community on red alert due to rain", "url": "https://www.elimparcial.es/noticia/303024/sociedad/andalucia-murcia-barcelona-y-la-comunidad-valenciana-en-alerta-roja-por-las-lluvias.html"}, {"language": "es", "published_at": "2026-10-18T18:30:00Z", "source_name": "cope.es", "title": "La dana Adam pone en alerta roja a Valencia, Alicante, Ibiza y Formentera por lluvias torrenciales", "title_en": "The DANA Adam puts Valencia, Alicante, Ibiza and Formentera on red alert for torrential rain", "url": "https://www.cope.es/actualidad/espana/al-minuto/dana-adam-pone-alerta-roja-valencia-alicante-ibiza-formentera-lluvias-torrenciales-20261018_3457770.html"}, {"language": "es", "published_at": "2026-10-18T18:45:00Z", "source_name": "lavanguardia.com", "title": "La dana obliga a suspender clases en Mallorca, Eivissa y Formentera y moviliza a la UME", "title_en": "The DANA forces class suspensions in Mallorca, Eivissa and Formentera and mobilises the UME", "url": "https://www.lavanguardia.com/vida/20261018/11662117/dana-obliga-suspender-clases-mallorca-eivissa-formentera-moviliza-ume.html"}, {"language": "es", "published_at": "2026-10-18T19:15:00Z", "source_name": "heraldo.es", "title": "La dana Adam deja una mujer muerta, moviliza a la UME y obliga a suspender las clases en Baleares", "title_en": "Dana Adam leaves one woman dead, mobilises the UME and forces class suspensions in the Balearic Islands", "url": "https://www.heraldo.es/noticias/nacional/2026/10/18/dana-adam-mujer-muerta-ume-baleares-alerta-roja-lluvias-dana-adam-mujer-muerta-ume-baleares-alerta-roja-lluvias-2060671.html"}], "summaries_original": {"es": "Una masa de aire frío y la formación de dos danas mantendrán la inestabilidad en España, con riesgo de inundaciones. Se han emitido alertas rojas para Valencia, Alicante, Ibiza y Formentera por lluvias torrenciales."}, "summary_en": "A cold air mass and two DANAs (cut-off low systems) are expected to sustain instability in Spain, with flood risk. Red alerts have been issued for Valencia, Alicante, Ibiza and Formentera due to torrential rain.", "title": "The DANA Adam puts Valencia, Alicante, Ibiza and Formentera on red alert for torrential rain", "wmo_regions": ["VI"]}');
