at": "2026-10-19T12:15:00Z", "source_name": "elperiodic.com", "title": "DANA Valencia y Alicante | Las im谩genes desde helic贸ptero que deja la DANA Adam: la Safor y la Marina se convierten en un mar", "title_en": "DANA Valencia and Alicante: helicopter images of the DANA Adam show the Safor and Marina regions turned into a sea", "url": "https://www.elperiodic.com/imagenes-desde-helicoptero-deja-dana-adam-safor-marina-convierten_1098269"}, {"language": "es", "published_at": "2026-10-19T12:31:48Z", "source_name": "El País (España)", "title": "Los vídeos de los rescates en la Comunidad Valenciana durante la dana ‘Adam’", "title_en": "Videos of the rescues in the Valencian Community during the DANA ''Adam''", "url": "https://elpais.com/videos/2026-10-19/los-videos-de-los-rescates-en-la-comunidad-valenciana-durante-la-dana-adam.html"}, {"language": "es", "published_at": "2026-10-19T15:45:00Z", "source_name": "diariodenavarra.es", "title": "La dana Adam se ceba en la Comunidad Valenciana con 3 muertos y deja cortes de luz y de carreteras en Baleares", "title_en": "Cut-off low ''Adam'' hits the Valencian Community with 3 deaths and leaves power and road cuts in the Balearic Islands", "url": "https://www.diariodenavarra.es/noticias/actualidad/nacional/2026/10/19/dana-adam-ceba-comunidad-valenciana-3-muertos-deja-cortes-luz-carreteras-baleares-839292-28.html"}, {"language": "en", "published_at": "2026-10-19T16:15:00Z", "source_name": "dailysabah.com", "title": "Heavy rain leaves at least 4 dead in eastern Spain", "title_en": "Heavy rain leaves at least 4 dead in eastern Spain", "url": "https://www.dailysabah.com/world/europe/heavy-rain-leaves-at-least-4-dead-in-eastern-spain"}, {"language": "es", "published_at": "2026-10-19T16:43:50Z", "source_name": "El País América", "title": "Andalucía y Cataluña, bajo aviso naranja por ‘Adam’ tras pasar lo peor en la Comunidad Valenciana y Baleares", "title_en": "Andalusia and Catalonia under orange alert for ''Adam'' after the worst has passed in Valencian Community and Balearic Islands", "url": "https://elpais.com/el-tiempo/2026-10-19/la-comunidad-valenciana-y-baleares-continuan-bajo-aviso-rojo-en-la-fase-mas-adversa-de-la-dana-adam.html"}, {"language": "es", "published_at": "2026-10-19T16:45:00Z", "source_name": "latribunadealbacete.es", "title": "La dana Adam deja cuatro muertos en España | Noticias La Tribuna de Albacete", "title_en": "The DANA Adam leaves four dead in Spain", "url": "https://www.latribunadealbacete.es/noticia/za594564a-1cd1-4b15-b6bf495235d48f80/202610/la-dana-adam-deja-cuatro-muertos-en-espana"}, {"language": "es", "published_at": "2026-10-19T17:30:00Z", "source_name": "diariodeburgos.es", "title": "La dana Adam deja cuatro muertos en España | Noticias Diario de Burgos", "title_en": "The DANA Adam leaves four dead in Spain", "url": "https://www.diariodeburgos.es/noticia/za594564a-1cd1-4b15-b6bf495235d48f80/202610/la-dana-adam-deja-cuatro-muertos-en-espana"}, {"language": "es", "published_at": "2026-10-19T19:15:00Z", "source_name": "cope.es", "title": "Última hora de la dana Adam: cuatro personas han fallecido y las lluvias fuertes continúan este lunes en Baleares y en la Comunidad Valenciana", "title_en": "Latest on DANA Adam: four people dead and heavy rain continues Monday in the Balearics and the Valencian Community", "url": "https://www.cope.es/actualidad/sociedad/al-minuto/ultima-hora-dana-adam-cuatro-personas-han-fallecido-lluvias-fuertes-continuan-lunes-baleares-comunidad-valenciana-20261019_3457850.html"}, {"language": "es", "published_at": "2026-10-19T21:30:00Z", "source_name": "lasprovincias.es", "title": "La dana Adam deja tres muertes, más de un millar de rescates y 720 litros en municipios de la Marina Alta", "title_en": "The DANA Adam leaves three dead, more than a thousand rescues and 720 litres in municipalities of the Marina Alta", "url": "https://www.lasprovincias.es/comunitat/dana-adam-deja-tres-muertes-millar-rescates-20261019230727-nt.html"}, {"language": "es", "published_at": "2026-10-19T23:15:00Z", "source_name": "publico.es", "title": "La DANA Adam deja cuatro muertos y causa inundaciones, cortes de carreteras y de luz en Balears", "title_en": "The DANA Adam leaves four dead and causes floods, road closures and power cuts in the Balearics", "url": "https://www.publico.es/sociedad/dana-adam-ceba-pais-valencia-tres-muertos-deja-interrupciones-luz-carreteras-cortadas-balears.html"}], "summaries_original": {"es": "Una actualización en directo informa de que los avisos rojos se mantienen en el sur de Valencia y el norte de Alicante por la DANA Adam, un peligro extraordinario en el Mediterráneo. El sistema ES-alert volvió a sonar y se suspendieron las clases, en lo que se describe como el peor momento del episodio."}, "summary_en": "A live news update reports that red warnings remain in place for southern Valencia and northern Alicante due to DANA Adam, described as an extraordinary Mediterranean hazard. The ES-alert emergency alert system was triggered again and classes were suspended, with the situation described as the worst moment of the event.", "title": "Latest on the storm, live: Extraordinary danger in the Mediterranean due to DANA Adam, with red warnings maintained in southern Valencia and northern Alicante", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(76,'','multi_hazard','2026-10-20T03:20:17Z','2026-10-20T03:07:51Z','2026-10-19','{"actions": ["Community-based preparedness", "Support for early warning systems", "Risk-informed planning", "Anticipatory action", "Mobility-sensitive recovery and resilience approaches"], "agencies": [{"country": null, "name": "International Organization for Migration (IOM)", "type": "international"}], "agency_types": ["international"], "channels": ["other"], "confidence": 0.6, "countries": [{"code": "PK", "name": "Pakistan"}, {"code": "SO", "name": "Somalia"}, {"code": "SS", "name": "South Sudan"}], "event_date": "2026-10-19", "event_location": null, "event_name": null, "first_seen": "2026-10-20T03:07:51Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 76, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-20T03:07:51Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The report is a retrospective programme achievements summary; no specific warning outcomes are given in the snippet.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-19T07:35:03Z", "source_name": "ReliefWeb - Updates", "title": "World: Disaster Risk Reduction: 2025 Key Achievements", "title_en": "World: Disaster Risk Reduction: 2025 Key Achievements", "url": "https://reliefweb.int/report/world/disaster-risk-reduction-2025-key-achievements"}], "summaries_original": {}, "summary_en": "IOM reports on its 2025 disaster risk reduction work supporting governments and communities to anticipate and recover from hazards. Activities cited include early warning systems, community-based preparedness and anticipatory action. The snippet provides no specific warning events or outcomes.", "title": "World: Disaster Risk Reduction: 2025 Key Achievements", "wmo_regions": ["I", "II"]}');
INSERT INTO "stories" VALUES(77,'drought|KE|karamoja region','drought','2026-10-20T03:20:18Z','2026-10-20T03:07:51Z','2026-10-19','{"actions": ["Community preparedness for El Niño"], "agencies": [{"country": null, "name": "International Federation of Red Cross and Red Crescent Societies", "type": "international"}], "agency_types": ["international"], "channels": [], "confidence": 0.6, "countries": [{"code": "KE", "name": "Kenya"}, {"code": "UG", "name": "Uganda"}], "event_date": "2026-10-19", "event_location": "Karamoja region, Uganda", "event_name": null, "first_seen": "2026-10-20T03:07:51Z", "hazard": "drought", "hazards": ["drought"], "id": 77, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-20T03:07:51Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes drought conditions and preparedness efforts but reports no outcome of warnings.", "pillars": [1, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-19T08:33:13Z", "source_name": "ReliefWeb - Updates", "title": "Uganda: Resilience starts at home: Preparing communities for El Niño before disaster strikes", "title_en": "Uganda: Resilience starts at home: Preparing communities for El Niño before disaster strikes", "url": "https://reliefweb.int/report/uganda/resilience-starts-home-preparing-communities-el-nino-disaster-strikes"}], "summaries_original": {}, "summary_en": "An IFRC report describes prolonged drought already affecting water and pasture in Karamoja, north-eastern Uganda, and frames community preparedness for an anticipated El Niño as a way to act before disaster strikes. The snippet focuses on risk knowledge and preparedness rather than specific forecasts or warnings issued.", "title": "Uganda: Resilience starts at home: Preparing communities for El Niño before disaster strikes", "wmo_regions": ["I"]}');
INSERT INTO "stories" VALUES(78,'flood|ES|badajoz','flood','2026-10-20T03:20:27Z','2026-10-20T03:14:37Z','2026-10-19','{"actions": ["Approval of a 1,854-page municipal flood plan coordinating response to high flood risk", "Identification of nine critical flood points in the municipality"], "agencies": [{"country": "ES", "name": "Ayuntamiento de Badajoz", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.7, "countries": [{"code": "ES", "name": "Spain"}], "event_date": "2026-10-19", "event_location": "Badajoz, Spain", "event_name": null, "first_seen": "2026-10-20T03:14:37Z", "hazard": "flood", "hazards": ["flood"], "id": 78, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-20T03:14:37Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item describes planning documents only; no warnings issued or outcomes reported.", "pillars": [1, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-19T12:30:00Z", "source_name": "hoy.es", "title": "El Plan de Inundaciones de Badajoz fija nueve puntos críticos, entre ellos la autopista y la Dehesilla de Calamón", "title_en": "Badajoz flood plan sets nine critical points, including the motorway and the Dehesilla de Calamón", "url": "https://www.hoy.es/badajoz/badajoz-publica-plan-municipal-inundaciones-ante-riesgo-20261019124945-nt.html"}], "summaries_original": {"es": "El documento de 1.854 páginas planifica la coordinación que debe existir ante el riesgo alto y la peligrosidad extrema de crecidas en el término municipal de Badajoz, fijando nueve puntos críticos."}, "summary_en": "Badajoz municipality published a 1,854-page municipal flood plan identifying nine critical points, including the motorway and the Dehesilla de Calamón, to coordinate response to high flood risk and extreme flood hazard in the municipal area. The plan addresses risk knowledge and preparedness, though the snippet does not describe warning dissemination or forecasting arrangements.", "title": "Badajoz flood plan sets nine critical points, including the motorway and the Dehesilla de Calamón", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(79,'','drought','2026-10-20T03:20:27Z','2026-10-20T03:07:52Z','2026-10-19','{"actions": ["planting and harvesting decisions based on sub-seasonal forecasts", "more efficient irrigation planning"], "agencies": [{"country": "IN", "name": "India Meteorological Department", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": [], "confidence": 0.7, "countries": [{"code": "IN", "name": "India"}], "event_date": "2026-10-19", "event_location": null, "event_name": null, "first_seen": "2026-10-20T03:07:52Z", "hazard": "drought", "hazards": ["drought"], "id": 79, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-20T03:07:52Z", "lead_time": "weeks ahead (sub-seasonal)", "outcome": "not_reported", "outcome_justification": "The snippet describes use of sub-seasonal forecasts for anticipatory planning but does not report measured outcomes.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-19T13:14:53Z", "source_name": "PreventionWeb", "title": "How Indian farmers use weather forecasts to plan weeks ahead", "title_en": "How Indian farmers use weather forecasts to plan weeks ahead", "url": "https://www.preventionweb.net/news/how-indian-farmers-use-weather-forecasts-plan-weeks-ahead"}], "summaries_original": {}, "summary_en": "India is using sub-seasonal forecasts to help farmers anticipate rainfall, drought and pest risks several weeks in advance. Examples show how longer-range weather information supports planting, harvesting and irrigation decisions. The snippet does not report quantified outcomes.", "title": "How Indian farmers use weather forecasts to plan weeks ahead", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(80,'','flood','2026-10-20T03:20:27Z','2026-10-20T03:07:52Z','2026-10-19','{"actions": ["Anticipatory action using established triggers and beneficiary registries", "Development of flood risk insurance and a Community Protection Fund for post-flood payouts"], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [{"code": "BD", "name": "Bangladesh"}], "event_date": "2026-10-19", "event_location": "Bangladesh", "event_name": null, "first_seen": "2026-10-20T03:07:52Z", "hazard": "flood", "hazards": ["flood"], "id": 80, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-20T03:07:52Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes an initiative under development and does not report measured outcomes of warnings.", "pillars": [3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-19T13:15:36Z", "source_name": "PreventionWeb", "title": "Leveraging anticipatory action for disaster risk finance: lessons from Bangladesh", "title_en": "Leveraging anticipatory action for disaster risk finance: lessons from Bangladesh", "url": "https://www.preventionweb.net/news/leveraging-anticipatory-action-disaster-risk-finance-lessons-bangladesh"}], "summaries_original": {}, "summary_en": "Bangladesh is building flood risk insurance and a Community Protection Fund by reusing its existing anticipatory action systems, including established flood triggers, beneficiary registries and delivery networks. The initiative adapts these early warning-linked mechanisms for post-flood payouts. The snippet does not report specific warning lead times or outcomes.", "title": "Leveraging anticipatory action for disaster risk finance: lessons from Bangladesh", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(81,'tropical_cyclone|AL|adriatic sea','storm_surge','2026-10-20T03:20:27Z','2026-10-20T03:07:52Z','2026-10-19','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [{"code": "AL", "name": "Albania"}, {"code": "HR", "name": "Croatia"}, {"code": "IT", "name": "Italy"}, {"code": "ME", "name": "Montenegro"}, {"code": "SI", "name": "Slovenia"}], "event_date": "2026-10-19", "event_location": "Adriatic Sea", "event_name": null, "first_seen": "2026-10-20T03:07:52Z", "hazard": "storm_surge", "hazards": ["storm_surge"], "id": 81, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-20T03:07:52Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a research evaluation of forecasting approaches for a past event; no warning dissemination or outcomes are reported.", "pillars": [2], "review": false, "sources": [{"language": "en", "published_at": "2026-10-19T14:19:25Z", "source_name": "PreventionWeb", "title": "Forecasting compound sea level extremes: the 29–30 October 2018 Adriatic storm surge and meteotsunami extreme", "title_en": "Forecasting compound sea level extremes: the 29–30 October 2018 Adriatic storm surge and meteotsunami extreme", "url": "https://www.preventionweb.net/publication/documents-and-publications/forecasting-compound-sea-level-extremes-29-30-october-2018"}], "summaries_original": {}, "summary_en": "This study uses the October 2018 extreme sea level event in the Adriatic Sea as a case study to evaluate two approaches for forecasting compound sea level extremes, combining storm surge and meteotsunami hazards. The work focuses on forecasting methodology, which relates to detection, monitoring, analysis and forecasting of the hazard. It does not report on warnings issued or their outcomes.", "title": "Forecasting compound sea level extremes: the 29–30 October 2018 Adriatic storm surge and meteotsunami extreme", "wmo_regions": ["VI"]}');
